INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l11','have nothing to declare','',NULL,'/hæv ˈnʌθɪŋ tuː dɪˈkler/','I have nothing to declare.','我没有需要申报的东西。','Travelers with nothing to declare use the green lane.','没有需申报物品的旅客走绿色通道。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l11','would you mind doing','',NULL,'/wʊd juː maɪnd ˈduːɪŋ/','Would you mind opening your suitcase?','你介意打开箱子吗?','Would you mind closing the window?','你介意关一下窗吗?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l11','should have done','',NULL,'/ʃʊd hæv dʌn/','You should have declared this.','这个你本该申报的(却没申报)。','I should have called you earlier.','我本该早点给你打电话的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l11','as I expected','',NULL,'/æz aɪ ɪkˈspektɪd/','As I expected, he did not believe me.','不出所料,他不信我。','As I expected, the store was closed.','不出所料,店关门了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp1','choice','{"stem":"转述句:把 ''I have nothing to declare'' 转述成 He said that he ___ nothing to declare.(时态后移)","options":["is having","have","has","had"],"answer_index":3,"stem_cn":"他说他没有什么要申报的。","explanation_cn":"转述别人的话时时态要后移一步:直接引语里的 have(一般现在)转述后变成 had。✓ He said that he had nothing to declare. ✗ has / have:没后移;✗ is having:have 表“有”不用进行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp1','choice','{"stem":"转述句:把 ''It is hair gel'' 转述成 I told him that it ___ hair gel.(时态后移)","options":["was","has been","is","are"],"answer_index":0,"stem_cn":"我告诉他那是发胶。","explanation_cn":"转述时 is 后移成 was。✓ I told him that it was hair gel. ✗ is / are:没后移或人称不对;✗ has been:时态不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp1','choice','{"stem":"转述句:把 ''I make it myself'' 转述成 I said that I ___ it myself.(时态后移)","options":["makes","make","made","making"],"answer_index":2,"stem_cn":"我说那是我自己配的。","explanation_cn":"转述时 make 后移成过去式 made。✓ I said that I made it myself. ✗ make / makes:没后移;✗ making:不是谓语形式。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp2','choice','{"stem":"转述句:把 ''Do you have anything to declare?'' 转述成 He asked ___ I had anything to declare.(转述''是否''的一般疑问,用哪个连词)","options":["that","whether","who","what"],"answer_index":1,"stem_cn":"他问我是否有东西要申报。","explanation_cn":"转述 Yes/No(一般)疑问句,用 whether 或 if 引导。✓ He asked whether I had anything to declare. ✗ that:那用于转述陈述句;✗ what / who:用于转述特殊疑问句。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp2','choice','{"stem":"转述句:把 ''Is this perfume?'' 转述成 He asked ___ that was perfume.(转述''是否'',用哪个连词)","options":["that","what","which","if"],"answer_index":3,"stem_cn":"他问那是不是香水。","explanation_cn":"转述一般疑问句可用 if(=whether)。✓ He asked if that was perfume. ✗ that:用于陈述句;✗ what / which:用于带疑问词的问句。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp2','choice','{"stem":"转述句:把 ''Will you open it?'' 转述成 He asked ___ I would open it.(转述''是否'',用哪个连词)","options":["that","whether","what","how"],"answer_index":1,"stem_cn":"他问我愿不愿意打开它。","explanation_cn":"转述一般疑问句用 whether/if。✓ He asked whether I would open it. ✗ that:陈述句才用;✗ what / how:这句原本没有这些疑问词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp3','choice','{"stem":"转述句:把 ''What is in the bottle?'' 转述成 He asked ___ was in the bottle.(保留疑问词)","options":["what","that","whether","if"],"answer_index":0,"stem_cn":"他问瓶子里是什么。","explanation_cn":"转述特殊疑问句要保留原来的疑问词 what,并把语序还原成陈述式。✓ He asked what was in the bottle. ✗ that / if / whether:都不能替代原来的 what。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp3','choice','{"stem":"转述句:把 ''Why are you so calm?'' 转述成 He asked ___ I was so calm.(保留疑问词)","options":["what","why","that","if"],"answer_index":1,"stem_cn":"他问我为什么这么镇定。","explanation_cn":"转述时保留疑问词 why,语序还原:why I was so calm。✓ He asked why I was so calm. ✗ that / if / what:替代不了 why。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp3','choice','{"stem":"转述句:把 ''Where did you buy it?'' 转述成 He asked ___ I had bought it.(保留疑问词、语序还原)","options":["if","that","where","whether"],"answer_index":2,"stem_cn":"他问我是在哪儿买的。","explanation_cn":"转述时保留 where,并把问句语序还原:where I had bought it(不是 where did I buy)。✓ He asked where I had bought it. ✗ that / if / whether:替代不了 where。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp4','choice','{"stem":"\"He ___ that the bottle was perfume.\"(后面不直接接人时,用哪个词的过去式)","options":["talked","said","told","spoke"],"answer_index":1,"stem_cn":"他说那瓶子里是香水。","explanation_cn":"say 后面一般不直接接“人”,直接接内容:He said that…。✓ He said that the bottle was perfume. ✗ told:told 后要接人;✗ spoke / talked:不这样接 that 从句。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp4','choice','{"stem":"\"I ___ him that it was only hair gel.\"(后面接人 him 时,用哪个词的过去式)","options":["told","talked","spoke","said"],"answer_index":0,"stem_cn":"我告诉他那只是发胶。","explanation_cn":"tell 后面要接“人”:tell sb that…。✓ I told him that it was hair gel. ✗ said:said 后不直接接人;✗ spoke / talked:不这样用。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp5','choice','{"stem":"下面哪句大小写正确?(星期几首字母要大写)","options":["We Arrived On Monday.","We arrived on Monday.","We arrived on monday.","we arrived on Monday."],"answer_index":1,"explanation_cn":"句首字母要大写,星期(Monday)首字母也要大写,其余单词不必大写。✓ We arrived on Monday. ✗ monday 没大写;✗ we 句首没大写;✗ 每个词都大写不对。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp5','choice','{"stem":"下面哪句大小写正确?(国家、国籍首字母要大写)","options":["he is from Canada and speaks English.","He is from canada and speaks english.","He Is From Canada And English.","He is from Canada and speaks English."],"answer_index":3,"explanation_cn":"国家名 Canada、语言/国籍 English 首字母要大写,句首 He 要大写,其余小写。✓ He is from Canada and speaks English. ✗ canada/english 没大写;✗ he 句首没大写;✗ 全大写不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp5','choice','{"stem":"下面哪句大小写正确?(月份首字母要大写)","options":["My trip was in july.","My Trip Was In July.","My trip was in July.","my trip was in July."],"answer_index":2,"explanation_cn":"月份 July 首字母要大写,句首 My 要大写,其余小写。✓ My trip was in July. ✗ july 没大写;✗ my 句首没大写;✗ 每词都大写不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp6','choice','{"stem":"\"A person who brings goods into a country illegally is a ___.\"(“走私者”用哪个词)","options":["doctor","teacher","farmer","smuggler"],"answer_index":3,"stem_cn":"非法把货物带进国家的人是走私者。","explanation_cn":"非法把货物偷带进出国境的人是 smuggler(走私者)。✓ a professional smuggler. ✗ teacher 老师;✗ farmer 农民;✗ doctor 医生——都不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp6','choice','{"stem":"\"To tell the customs what you are bringing in is to ___ it.\"(“申报”用哪个词)","options":["declare","hide","destroy","lose"],"answer_index":0,"stem_cn":"把带进来的东西告诉海关就是申报。","explanation_cn":"把带进来的东西告诉海关、如实上报就是 declare(申报)。✓ declare it. ✗ hide 隐藏;✗ destroy 毁坏;✗ lose 丢失——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp6','choice','{"stem":"\"An officer who loves to interfere in a bossy way is ___.\"(“爱管闲事的”用哪个词)","options":["generous","gentle","officious","lazy"],"answer_index":2,"stem_cn":"爱指手画脚、多管闲事的官员是 officious。","explanation_cn":"爱指手画脚、过分多管闲事的用 officious。✓ an officious officer. ✗ generous 慷慨的;✗ gentle 温和的;✗ lazy 懒惰的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',5,'am3_l11_gp6','choice','{"stem":"\"Tax you pay on goods brought into a country is import ___.\"(“税”用哪个词)","options":["duty","prize","menu","gift"],"answer_index":0,"stem_cn":"带货物进国家要交的税是进口税。","explanation_cn":"带货物进国要交的税叫 duty(关税);import duty 进口税。✓ import duty. ✗ gift 礼物;✗ prize 奖品;✗ menu 菜单——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',6,NULL,'choice','{"stem":"smuggler 的意思是:","options":["走私者","游客","司机","海关官员"],"answer_index":0,"explanation_cn":"smuggler = 走私者(非法偷带货物过境的人)。✓ a professional smuggler 职业走私犯。\n顺带记:海关官员 = customs officer;游客 = tourist;司机 = driver."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',6,NULL,'choice','{"stem":"declare 的意思是:","options":["丢弃","隐藏","打碎","(向海关)申报"],"answer_index":3,"explanation_cn":"declare = (向海关)申报、如实上报。✓ anything to declare 有什么要申报的。\n顺带记:隐藏 = hide;丢弃 = throw away;打碎 = break."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',6,NULL,'choice','{"stem":"officious 的意思是:","options":["爱管闲事的","害羞的","诚实的","慷慨的"],"answer_index":0,"explanation_cn":"officious = 爱管闲事的、爱指手画脚的。✓ an officious officer 一个爱多管闲事的官员。\n顺带记:慷慨的 = generous;害羞的 = shy;诚实的 = honest."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',6,NULL,'choice','{"stem":"dreadful 的意思是:","options":["美好的","安静的","便宜的","可怕的,一团糟的"],"answer_index":3,"explanation_cn":"dreadful = 可怕的、糟糕透顶的。✓ a dreadful mess 一团糟。\n顺带记:美好的 = wonderful;便宜的 = cheap;安静的 = quiet."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',6,NULL,'choice','{"stem":"\"exempt\" 的意思是:","options":["被免除的,豁免的","危险的","昂贵的","必须的"],"answer_index":0,"explanation_cn":"exempt = 被免除的、可豁免的。✓ not exempt from duty 不免税。\n顺带记:必须的 = necessary;昂贵的 = expensive;危险的 = dangerous."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',6,NULL,'choice','{"stem":"unscrew 的意思是:","options":["打碎","拧开,旋松","拧紧","粘牢"],"answer_index":1,"explanation_cn":"unscrew = 拧开、旋松(盖子等)。✓ unscrewed the cap 拧开盖子。\n顺带记:拧紧 = tighten;打碎 = smash;粘牢 = stick."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',7,NULL,'cloze','{"stem":"第 1 空","context":"The customs officer asked me ___1___ I had anything to declare. I told him that I ___2___ nothing to hide. He then asked ___3___ was in the small bottle. I said it ___4___ only homemade hair gel, and after one smell, he let me go.","blank_no":1,"options":["that","whether","what","why"],"answer_index":1,"explanation_cn":"转述一般疑问句用 whether(或 if)。✓ asked whether I had anything to declare."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',7,NULL,'cloze','{"stem":"第 2 空","context":"The customs officer asked me ___1___ I had anything to declare. I told him that I ___2___ nothing to hide. He then asked ___3___ was in the small bottle. I said it ___4___ only homemade hair gel, and after one smell, he let me go.","blank_no":2,"options":["had","have","has","having"],"answer_index":0,"explanation_cn":"转述陈述句时态后移,have→had。✓ I told him that I had nothing to hide."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',7,NULL,'cloze','{"stem":"第 3 空","context":"The customs officer asked me ___1___ I had anything to declare. I told him that I ___2___ nothing to hide. He then asked ___3___ was in the small bottle. I said it ___4___ only homemade hair gel, and after one smell, he let me go.","blank_no":3,"options":["what","that","if","whether"],"answer_index":0,"explanation_cn":"转述特殊疑问句保留疑问词 what,语序还原。✓ He asked what was in the bottle."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',7,NULL,'cloze','{"stem":"第 4 空","context":"The customs officer asked me ___1___ I had anything to declare. I told him that I ___2___ nothing to hide. He then asked ___3___ was in the small bottle. I said it ___4___ only homemade hair gel, and after one smell, he let me go.","blank_no":4,"options":["is","was","are","being"],"answer_index":1,"explanation_cn":"转述时 is 后移成 was。✓ I said it was only hair gel."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',8,NULL,'choice','{"stem":"Why did the young officer stop the traveler?","options":["The traveler was famous","The traveler had no ticket","He suspected the traveler was a smuggler","The plane was late"],"answer_index":2,"explanation_cn":"课文说 one very officious young officer clearly decided that I was up to something——他怀疑“我”在走私。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',8,NULL,'choice','{"stem":"What did the officer think was in the small bottle?","options":["Medicine","Undeclared perfume","A pile of money","Gold watches"],"answer_index":1,"explanation_cn":"课文说 ''Perfume, isn''t it? You should have declared this.''——他以为瓶里是没申报的香水。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',8,NULL,'choice','{"stem":"What was really in the bottle?","options":["Homemade hair gel","Nothing at all","Expensive perfume","Cold soup"],"answer_index":0,"explanation_cn":"课文说 ''It''s homemade hair gel, a little mixture I make myself.''——其实是自制发胶。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',9,NULL,'choice','{"stem":"你想说\"他问我是否有东西要申报\"(ask + whether/if):","options":["He asked that I had anything to declare.","He asked do I have anything to declare.","He asked me whether do I have anything to declare.","He asked whether I had anything to declare."],"answer_index":3,"explanation_cn":"转述一般疑问句用 whether,并把问句语序还原成陈述式(I had,不是 do I have)。✓ He asked whether I had anything to declare. 场合:转述别人问的 Yes/No 问题。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',9,NULL,'choice','{"stem":"你想说\"我告诉他那是发胶\"(tell sb that):","options":["I told him that it was hair gel.","I told to him that it was hair gel.","I told him that it is hair gel.","I said him that it was hair gel."],"answer_index":0,"explanation_cn":"tell 后面要接人 him;转述时 is 后移成 was。✓ I told him that it was hair gel. 场合:告诉某人某事(tell sb that…)。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',9,NULL,'choice','{"stem":"你想说\"他问我东西是在哪儿买的\"(ask + where,语序还原):","options":["He asked where had I bought it.","He asked where did I buy it.","He asked where I had bought it.","He asked me where do I buy it."],"answer_index":2,"explanation_cn":"转述特殊疑问句保留 where、语序还原成陈述式(I had bought,不是 did I buy)。✓ He asked where I had bought it. 场合:转述别人问“在哪儿……”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"smuggler 的意思是:","options":["游客","海关官员","走私者","司机"],"answer_index":2,"explanation_cn":"smuggler = 走私者。✓ a professional smuggler."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"exempt 的意思是:","options":["昂贵的","被免除的,豁免的","危险的","必须的"],"answer_index":1,"explanation_cn":"exempt = 被免除的、可豁免的。✓ not exempt from duty 不免税。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"\"He said that the bottle ___ hair gel.\"(转述陈述,is 后移)","options":["been","is","are","was"],"answer_index":3,"stem_cn":"他说那瓶子里是发胶。","explanation_cn":"转述陈述句时态后移,is→was。✓ He said that the bottle was hair gel. ✗ is / are / been:没后移或形式不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"\"He asked ___ I had anything to declare.\"(转述一般疑问,用“是否”)","options":["why","what","whether","that"],"answer_index":2,"stem_cn":"他问我是否有东西要申报。","explanation_cn":"转述一般疑问句用 whether(“是否”)。✓ He asked whether I had anything to declare. ✗ that / what / why:不用于转述这种 Yes/No 问句。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"\"have nothing to declare\" 的意思是:","options":["没钱付款","没有需要申报的东西","没带行李","没时间排队"],"answer_index":1,"explanation_cn":"have nothing to declare = 没有需要向海关申报的东西。✓ I have nothing to declare."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"\"should have declared\" 的意思是:","options":["本该申报却没申报","将要申报","禁止申报","正在申报"],"answer_index":0,"explanation_cn":"should have declared = 本来应该申报(可惜没申报)。✓ You should have declared this."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"How did the traveler prove the bottle was not perfume?","options":["He drank it","He showed a receipt","He poured it out","He let the officer smell it"],"answer_index":3,"passage":"These days, customs officers are usually quite tolerant, but they can still stop you in the ''Nothing to Declare'' lane and make even honest travelers feel guilty. A hardened, professional smuggler, of course, stays perfectly calm, even with a suitcase full of hidden watches. When I flew home from a trip abroad last month, one very officious young officer clearly decided that I was up to something. ''Do you have anything to declare?'' he asked, looking me straight in the eye. ''No,'' I answered confidently. ''Would you mind opening your suitcase?'' he said. ''Not at all,'' I told him. He went through my case with great care, and everything I had packed so neatly was soon in a dreadful mess. Suddenly his eyes lit up: he had spotted a small bottle at the bottom and pounced on it. ''Perfume, isn''t it?'' he asked sarcastically. ''You should have declared this. Perfume is not exempt from import duty.'' ''It isn''t perfume,'' I said with a smile. ''It''s homemade hair gel, a little mixture I make myself.'' As I expected, he did not believe me. ''Try it!'' I said. He unscrewed the cap and lifted the bottle to his nostrils. The smell was so dreadful that he was instantly convinced I was telling the truth. A few minutes later, an officer marked my baggage with chalk, and I hurried away, innocent after all.","explanation_cn":"课文说 ''Try it!'' … He unscrewed the cap and lifted the bottle to his nostrils——让官员闻一闻,气味证明不是香水。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"How did the story end?","options":["The traveler was allowed to go, innocent","The bottle was taken away","The officer bought the gel","The traveler was arrested"],"answer_index":0,"passage":"These days, customs officers are usually quite tolerant, but they can still stop you in the ''Nothing to Declare'' lane and make even honest travelers feel guilty. A hardened, professional smuggler, of course, stays perfectly calm, even with a suitcase full of hidden watches. When I flew home from a trip abroad last month, one very officious young officer clearly decided that I was up to something. ''Do you have anything to declare?'' he asked, looking me straight in the eye. ''No,'' I answered confidently. ''Would you mind opening your suitcase?'' he said. ''Not at all,'' I told him. He went through my case with great care, and everything I had packed so neatly was soon in a dreadful mess. Suddenly his eyes lit up: he had spotted a small bottle at the bottom and pounced on it. ''Perfume, isn''t it?'' he asked sarcastically. ''You should have declared this. Perfume is not exempt from import duty.'' ''It isn''t perfume,'' I said with a smile. ''It''s homemade hair gel, a little mixture I make myself.'' As I expected, he did not believe me. ''Try it!'' I said. He unscrewed the cap and lifted the bottle to his nostrils. The smell was so dreadful that he was instantly convinced I was telling the truth. A few minutes later, an officer marked my baggage with chalk, and I hurried away, innocent after all.","explanation_cn":"课文说 I hurried away, innocent after all——最后“我”清清白白地离开了。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"What did the customs officer suspect the traveler of?","options":["Losing a passport","Missing a flight","Being a tourist","Smuggling or hiding goods"],"answer_index":3,"audio":"These days, customs officers are usually quite tolerant, but they can still stop you in the ''Nothing to Declare'' lane and make even honest travelers feel guilty. A hardened, professional smuggler, of course, stays perfectly calm, even with a suitcase full of hidden watches. When I flew home from a trip abroad last month, one very officious young officer clearly decided that I was up to something. ''Do you have anything to declare?'' he asked, looking me straight in the eye. ''No,'' I answered confidently. ''Would you mind opening your suitcase?'' he said. ''Not at all,'' I told him. He went through my case with great care, and everything I had packed so neatly was soon in a dreadful mess. Suddenly his eyes lit up: he had spotted a small bottle at the bottom and pounced on it. ''Perfume, isn''t it?'' he asked sarcastically. ''You should have declared this. Perfume is not exempt from import duty.'' ''It isn''t perfume,'' I said with a smile. ''It''s homemade hair gel, a little mixture I make myself.'' As I expected, he did not believe me. ''Try it!'' I said. He unscrewed the cap and lifted the bottle to his nostrils. The smell was so dreadful that he was instantly convinced I was telling the truth. A few minutes later, an officer marked my baggage with chalk, and I hurried away, innocent after all.","explanation_cn":"课文说官员认定 I was up to something、把“我”当走私犯——他怀疑的是走私/藏匿货物。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l11',10,NULL,'choice','{"stem":"How did the officer react to the smell?","options":["He bought a bottle","He was convinced the traveler told the truth","He fainted at once","He loved the smell"],"answer_index":1,"audio":"These days, customs officers are usually quite tolerant, but they can still stop you in the ''Nothing to Declare'' lane and make even honest travelers feel guilty. A hardened, professional smuggler, of course, stays perfectly calm, even with a suitcase full of hidden watches. When I flew home from a trip abroad last month, one very officious young officer clearly decided that I was up to something. ''Do you have anything to declare?'' he asked, looking me straight in the eye. ''No,'' I answered confidently. ''Would you mind opening your suitcase?'' he said. ''Not at all,'' I told him. He went through my case with great care, and everything I had packed so neatly was soon in a dreadful mess. Suddenly his eyes lit up: he had spotted a small bottle at the bottom and pounced on it. ''Perfume, isn''t it?'' he asked sarcastically. ''You should have declared this. Perfume is not exempt from import duty.'' ''It isn''t perfume,'' I said with a smile. ''It''s homemade hair gel, a little mixture I make myself.'' As I expected, he did not believe me. ''Try it!'' I said. He unscrewed the cap and lifted the bottle to his nostrils. The smell was so dreadful that he was instantly convinced I was telling the truth. A few minutes later, an officer marked my baggage with chalk, and I hurried away, innocent after all.","explanation_cn":"课文说 The smell was so dreadful that he was convinced I was telling the truth——难闻的气味让他相信了。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l12',3,3,12,'Life on a Desert Island','荒岛生活','条件句 if(真实条件:if + 一般现在, will do;与现在相反的虚拟:if + 过去时, would do / if I were you;与过去相反的虚拟:if + had done, would have done),外加 wish / if only + 过去时(与现在相反的愿望)/ 过去完成(对过去的懊悔)(原创承载 NCE3 L12 考点·两人在珊瑚岛意外过了五天惬意的荒岛生活)','我们大多数人对荒岛生活的想象都很不真实。我们爱把它当成一种乐园:阳光永远灿烂,熟果从树上落下,谁也不必干活。可另一面恰恰相反:孤岛上的日子也可能十分凄惨,一个落难者也许会像鲁滨孙那样慢慢挨饿,苦等一艘永远不来的船。这两幅画面里也许都有一点真实成分,可我们很少有人有机会亲身去验证。最近有两个朋友在一座小珊瑚岛上待了五天,却真希望当时能待得更久。他们本是驾着一条严重受损的小船,从维尔京群岛开往迈阿密去修理,途中船开始进水下沉。他们手脚麻利地往一条橡皮小艇里装了食物、火柴和几罐汽水,划了好几英里,横渡加勒比海,来到一座小珊瑚岛。岛上几乎没有树,也没有淡水,可这并没成为问题:他们用橡皮艇接雨水。因为带了一把捕鱼枪,他们吃得很足——天天捕龙虾和鱼,用其中一人的话说,他们“吃得像国王”。五天后一艘过路油轮救了他们,两人都由衷地舍不得离开。要不是那艘油轮恰好路过,谁知道他们还会再待多久呢!','{"q":"Listen and answer — What was exceptional about the two men''s stay on the island?","options":["They enjoyed it and were sorry to leave","They hated every minute","They were badly hurt","They never found any food"],"answer_index":0}'::jsonb,'{"title":"条件句 if + 虚拟愿望 wish / if only","intro":"①真实条件:很可能发生,if 从句用一般现在时,主句用将来时——If it rains, we will stay。②与现在事实相反的虚拟:if 从句用过去时,主句 would do;be 动词一律用 were——If I were you, I would go。③与过去事实相反的虚拟:if 从句用过去完成,主句 would have done——If they had not brought a gun, they would have starved。④表示愿望用 wish 或 if only:对现在的愿望用过去时(I wish I knew…),对过去的懊悔用过去完成(They wished they had stayed longer / If only I had known!)。","table":{"headers":["类型","if / wish 后","主句/例子"],"rows":[["真实条件","一般现在时","If it rains, we will stay home."],["与现在相反","过去时(be 用 were)","If I were you, I would go."],["与过去相反","过去完成","If they had come, they would have seen it."],["愿望 wish/if only","过去时(现在)/ 过去完成(过去)","I wish I knew. / They wished they had stayed."]]},"specialRules":[{"rule":"虚拟里 be 动词一律用 were,不分人称:If I were you… / I wish he were here。","mark":"were"},{"rule":"wish/if only 后:想改变现在的状况用过去时(I wish I had a boat 现在没有),后悔过去的事用过去完成(I wish I hadn''t said that 过去说了)。","mark":"wish + 过去/过去完成"},{"rule":"美语里“汽水”常说 soda(英式 fizzy drink);“(易拉)罐”说 can(英式 tin)。本课已按美语写。","mark":"soda / can"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l12',1,NULL,'Most of us have a very unrealistic picture of life on a desert island. We like to imagine it as a kind of paradise, where the sun always shines, ripe fruit drops from the trees, and no one ever has to work.','我们大多数人对荒岛生活的想象都很不真实。我们爱把它当成一种乐园:阳光永远灿烂,熟果从树上落下,谁也不必干活。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l12',2,NULL,'The other side of the picture is quite the opposite: life on a lonely island can be wretched, and a castaway may slowly starve, like Robinson Crusoe, waiting for a boat that never comes. There is probably an element of truth in both pictures, but few of us ever get the opportunity to find out.','可另一面恰恰相反:孤岛上的日子也可能十分凄惨,一个落难者也许会像鲁滨孙那样慢慢挨饿,苦等一艘永远不来的船。这两幅画面里也许都有一点真实成分,可我们很少有人有机会亲身去验证。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l12',3,NULL,'Two friends who recently spent five days on a tiny coral island wished they had stayed even longer. They had been sailing a badly damaged boat from the Virgin Islands to Miami to have it repaired when, halfway across, it began to sink.','最近有两个朋友在一座小珊瑚岛上待了五天,却真希望当时能待得更久。他们本是驾着一条严重受损的小船,从维尔京群岛开往迈阿密去修理,途中船开始进水下沉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l12',4,NULL,'Working fast, they loaded a small rubber dinghy with food, matches, and cans of soda, and rowed for miles across the Caribbean until they reached a coral island. There were almost no trees and no fresh water, but that did not turn out to be a problem: the men caught rainwater in the dinghy.','他们手脚麻利地往一条橡皮小艇里装了食物、火柴和几罐汽水,划了好几英里,横渡加勒比海,来到一座小珊瑚岛。岛上几乎没有树,也没有淡水,可这并没成为问题:他们用橡皮艇接雨水。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l12',5,NULL,'Because they had packed a spear gun, they had plenty to eat. Every day they caught lobster and fish, and, as one of them said, they ''ate like kings.'' When a passing tanker rescued them five days later, both men were genuinely sorry to leave.','因为带了一把捕鱼枪,他们吃得很足——天天捕龙虾和鱼,用其中一人的话说,他们“吃得像国王”。五天后一艘过路油轮救了他们,两人都由衷地舍不得离开。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
