INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l12','vacation','holiday','假期;美语 vacation,英式 holiday') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l12','flashlight','torch','手电筒;美语 flashlight,英式 torch') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l12','quite the opposite','',NULL,'/kwaɪt ði ˈɑːpəzɪt/','The other side is quite the opposite.','另一面恰恰相反。','I thought it was easy, but it was quite the opposite.','我以为很容易,结果恰恰相反。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l12','starve to death','',NULL,'/stɑːrv tuː deθ/','A castaway might starve to death.','落难者可能会饿死。','No one should starve to death in a rich country.','在富裕国家不该有人饿死。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l12','eat like a king','',NULL,'/iːt laɪk ə kɪŋ/','They ate like kings on the island.','他们在岛上吃得像国王一样好。','At the festival, we ate like kings.','节日里我们吃得极好。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l12','turn out to be','',NULL,'/tɜːrn aʊt tuː biː/','It did not turn out to be a problem.','结果这并没成为问题。','The stranger turned out to be a friend.','那个陌生人原来是个朋友。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp1','choice','{"stem":"\"If it rains tomorrow, we ___ the boat trip.\"(真实条件:if 一般现在,主句将来时)","options":["cancel","would cancel","cancelled","will cancel"],"answer_index":3,"stem_cn":"如果明天下雨,我们就取消坐船的行程。","explanation_cn":"真实条件:很可能发生,if 从句用一般现在时(rains),主句用将来时 will do。✓ If it rains, we will cancel the trip. ✗ cancel:主句要用将来时;✗ would cancel:那是虚拟;✗ cancelled:时态不对。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp1','choice','{"stem":"\"You ___ hungry if you don''t catch any fish.\"(真实条件:主句将来时)","options":["would be","will be","are being","were"],"answer_index":1,"stem_cn":"如果你钓不到鱼,就会饿。","explanation_cn":"真实条件的主句用将来时:will be hungry。✓ You will be hungry if you don''t catch any fish. ✗ would be:那是虚拟;✗ are being / were:时态或语气不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp2','choice','{"stem":"\"If I ___ you, I would stay on that island longer.\"(与现在相反的虚拟:be 用哪个)","options":["am","will be","was","were"],"answer_index":3,"stem_cn":"如果我是你,我会在那岛上多待些时候。","explanation_cn":"与现在事实相反的虚拟里,be 动词一律用 were,不分人称:If I were you…。✓ If I were you, I would stay longer. ✗ am / was:虚拟里固定用 were;✗ will be:那是真实条件。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp2','choice','{"stem":"\"If they ___ a spear gun now, they could catch fish easily.\"(与现在相反:if 从句用过去时)","options":["have","will have","had","has"],"answer_index":2,"stem_cn":"如果他们现在有一把鱼枪,就能轻松捕鱼。","explanation_cn":"与现在事实相反的虚拟,if 从句用过去时:If they had a gun now…(其实现在没有)。✓ If they had a spear gun now, they could catch fish. ✗ have:那是真实/现在;✗ will have / has:语气或人称不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp2','choice','{"stem":"\"If the island ___ fresh water, life there would be easier.\"(与现在相反的虚拟)","options":["would have","had","will have","has"],"answer_index":1,"stem_cn":"如果岛上有淡水,生活会容易些。","explanation_cn":"与现在相反的虚拟,if 从句用过去时 had(其实岛上没淡水)。✓ If the island had fresh water, life would be easier. ✗ has / will have:不是虚拟;✗ would have:would 用在主句,不用在 if 从句。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp3','choice','{"stem":"\"If the boat had not started to sink, they ___ on it.\"(与过去相反:主句 would have + 过去分词)","options":["stay","will stay","stayed","would have stayed"],"answer_index":3,"stem_cn":"要是船没开始下沉,他们本会留在船上。","explanation_cn":"与过去事实相反的虚拟,主句用 would have + 过去分词。✓ If the boat had not sunk, they would have stayed on it. ✗ stayed / will stay / stay:配不出“与过去相反”的虚拟。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp3','choice','{"stem":"\"If that tanker ___ come along, they might have stayed for weeks.\"(与过去相反:if 从句用过去完成)","options":["did not","had not","does not","would not"],"answer_index":1,"stem_cn":"要是那艘油轮没恰好路过,他们可能还得待上几周。","explanation_cn":"与过去相反的虚拟,if 从句用过去完成(had done / had not done)。✓ If that tanker had not come along… ✗ did not / does not / would not:配不出对过去的虚拟。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp3','choice','{"stem":"\"They ___ if they had not brought the spear gun.\"(与过去相反:主句 might have + 过去分词)","options":["starved","would starve","might have starved","starve"],"answer_index":2,"stem_cn":"要是他们没带鱼枪,可能就挨饿了。","explanation_cn":"与过去相反的虚拟,主句用 might/would have + 过去分词。✓ They might have starved if they had not brought the gun. ✗ starved / would starve / starve:配不出对过去的虚拟。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp4','choice','{"stem":"\"I wish I ___ how to fish like those two men.\"(与现在相反的愿望:wish + 过去时)","options":["knew","know","have known","will know"],"answer_index":0,"stem_cn":"我真希望自己像那两人一样会捕鱼。","explanation_cn":"对现在的愿望(其实不会)用 wish + 过去时:I wish I knew…。✓ I wish I knew how to fish. ✗ know:愿望要用过去时表现在;✗ will know / have known:时态不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp4','choice','{"stem":"\"The castaways wish the island ___ more trees for shade.\"(与现在相反的愿望:wish + 过去时)","options":["have","had","will have","has"],"answer_index":1,"stem_cn":"落难者们真希望岛上多些树好遮阴。","explanation_cn":"wish + 过去时表示“但愿现在……(其实没有)”:wish the island had more trees。✓ wish the island had more trees. ✗ has / will have / have:配不出这种虚拟愿望。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp4','choice','{"stem":"\"I wish I ___ a boat right now to sail away.\"(与现在相反的愿望:wish + 过去时)","options":["will have","have","had","would have"],"answer_index":2,"stem_cn":"我真希望现在有条船可以开走。","explanation_cn":"wish + 过去时表示“但愿现在有(其实没有)”:I wish I had a boat now。✓ I wish I had a boat right now. ✗ have / will have / would have:配不出虚拟愿望。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp5','choice','{"stem":"\"The two men wished they ___ longer on the island.\"(对过去的愿望:wish + 过去完成)","options":["had stayed","stay","have stayed","stayed"],"answer_index":0,"stem_cn":"那两人真希望当时在岛上多待些时候。","explanation_cn":"对过去的愿望/懊悔用 wish + 过去完成:wished they had stayed longer(当时没多待)。✓ The men wished they had stayed longer. ✗ stayed / stay / have stayed:配不出对过去的虚拟愿望。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp5','choice','{"stem":"\"If only they ___ more matches before the boat sank!\"(对过去的懊悔:if only + 过去完成)","options":["bring","had brought","brought","have brought"],"answer_index":1,"stem_cn":"要是船沉之前他们多带些火柴就好了!","explanation_cn":"if only + 过去完成,表示对过去的懊悔(当时没多带)。✓ If only they had brought more matches! ✗ brought / bring / have brought:配不出对过去的懊悔。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp5','choice','{"stem":"\"I wish I ___ so much money on that trip.\"(对过去的懊悔:wish + hadn''t done)","options":["haven''t spent","didn''t spend","don''t spend","hadn''t spent"],"answer_index":3,"stem_cn":"我真后悔那趟旅行花了那么多钱。","explanation_cn":"对过去的懊悔用 wish + hadn''t done(当时花了太多钱)。✓ I wish I hadn''t spent so much money. ✗ didn''t spend / don''t spend / haven''t spent:配不出对过去的虚拟懊悔。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp6','choice','{"stem":"\"A small island built up by tiny sea creatures is a ___ island.\"(“珊瑚”用哪个词)","options":["coral","glass","paper","metal"],"answer_index":0,"stem_cn":"由微小海洋生物堆积成的小岛是珊瑚岛。","explanation_cn":"由微小海洋生物长年堆积成的岛是 coral island(珊瑚岛)。✓ a coral island. ✗ metal 金属;✗ paper 纸;✗ glass 玻璃——都不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp6','choice','{"stem":"\"A person left alone on a lonely island is a ___.\"(“漂流者、落难者”用哪个词)","options":["passenger","champion","customer","castaway"],"answer_index":3,"stem_cn":"被独自留在孤岛上的人是落难者。","explanation_cn":"遭遇海难、被独自留在孤岛上的人是 castaway(落难者、漂流者)。✓ a castaway. ✗ champion 冠军;✗ customer 顾客;✗ passenger 乘客——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp6','choice','{"stem":"\"A big ship that carries oil is a ___.\"(“油轮”用哪个词)","options":["wagon","tanker","kite","bicycle"],"answer_index":1,"stem_cn":"运油的大船是油轮。","explanation_cn":"专门运油的大船是 tanker(油轮)。✓ a passing tanker. ✗ bicycle 自行车;✗ wagon 货车;✗ kite 风筝——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',5,'am3_l12_gp6','choice','{"stem":"\"To suffer or die from lack of food is to ___.\"(“挨饿”用哪个词)","options":["celebrate","travel","relax","starve"],"answer_index":3,"stem_cn":"因缺食物而受苦或饿死就是 starve。","explanation_cn":"因缺食物而受苦、饿死用 starve(挨饿)。✓ they might starve. ✗ relax 放松;✗ celebrate 庆祝;✗ travel 旅行——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',6,NULL,'choice','{"stem":"paradise 的意思是:","options":["监狱","沙漠","地狱","天堂,乐土"],"answer_index":3,"explanation_cn":"paradise = 天堂、乐土。✓ a kind of paradise 一种乐园。\n顺带记:地狱 = hell;沙漠 = desert;监狱 = prison."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',6,NULL,'choice','{"stem":"wretched 的意思是:","options":["富裕的","幸福的","可怜的,艰苦的","热闹的"],"answer_index":2,"explanation_cn":"wretched = 可怜的、凄惨艰苦的。✓ life can be wretched 日子可能很凄惨。\n顺带记:幸福的 = happy;富裕的 = rich;热闹的 = lively."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',6,NULL,'choice','{"stem":"starve 的意思是:","options":["大笑","挨饿","睡觉","唱歌"],"answer_index":1,"explanation_cn":"starve = 挨饿、饿死。✓ slowly starve 慢慢挨饿。\n顺带记:大笑 = laugh;睡觉 = sleep;唱歌 = sing."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',6,NULL,'choice','{"stem":"genuinely 的意思是:","options":["偶尔地","假装地","大声地","由衷地,真诚地"],"answer_index":3,"explanation_cn":"genuinely = 由衷地、真诚地。✓ genuinely sorry 由衷地遗憾。\n顺带记:假装地 = pretendingly;偶尔地 = occasionally;大声地 = loudly."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',6,NULL,'choice','{"stem":"\"opportunity\" 的意思是:","options":["机会","秘密","麻烦","危险"],"answer_index":0,"explanation_cn":"opportunity = 机会。✓ get the opportunity to find out 有机会去弄清楚。\n顺带记:危险 = danger;麻烦 = trouble;秘密 = secret."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',6,NULL,'choice','{"stem":"dinghy 的意思是:","options":["油轮","救生筏,小艇","飞机","火车"],"answer_index":1,"explanation_cn":"dinghy = 小艇、救生筏(充气或小型的船)。✓ a rubber dinghy 橡皮小艇。\n顺带记:油轮 = tanker;火车 = train;飞机 = plane."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',7,NULL,'cloze','{"stem":"第 1 空","context":"Two men wished they ___1___ longer on the desert island. If they ___2___ brought a spear gun, they would have gone hungry. Luckily, they had one, so they ate well. ''I wish every trip ___3___ this much fun,'' one of them joked. If only the rescue ship ___4___ come a little later!","blank_no":1,"options":["stayed","had stayed","stay","have stayed"],"answer_index":1,"explanation_cn":"对过去的愿望用 wish + 过去完成:wished they had stayed longer。✓ They wished they had stayed longer."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',7,NULL,'cloze','{"stem":"第 2 空","context":"Two men wished they ___1___ longer on the desert island. If they ___2___ brought a spear gun, they would have gone hungry. Luckily, they had one, so they ate well. ''I wish every trip ___3___ this much fun,'' one of them joked. If only the rescue ship ___4___ come a little later!","blank_no":2,"options":["had not","did not","have not","were not"],"answer_index":0,"explanation_cn":"与过去相反的虚拟,if 从句用过去完成(had not brought)。✓ If they had not brought a spear gun, they would have gone hungry."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',7,NULL,'cloze','{"stem":"第 3 空","context":"Two men wished they ___1___ longer on the desert island. If they ___2___ brought a spear gun, they would have gone hungry. Luckily, they had one, so they ate well. ''I wish every trip ___3___ this much fun,'' one of them joked. If only the rescue ship ___4___ come a little later!","blank_no":3,"options":["was","were","is","will be"],"answer_index":1,"explanation_cn":"wish 后的虚拟里,be 动词用 were:wish every trip were this much fun。✓ I wish every trip were this much fun."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',7,NULL,'cloze','{"stem":"第 4 空","context":"Two men wished they ___1___ longer on the desert island. If they ___2___ brought a spear gun, they would have gone hungry. Luckily, they had one, so they ate well. ''I wish every trip ___3___ this much fun,'' one of them joked. If only the rescue ship ___4___ come a little later!","blank_no":4,"options":["had","has","have","did"],"answer_index":0,"explanation_cn":"if only + 过去完成,表示对过去的假设/懊悔:if only the ship had come later。✓ If only the rescue ship had come a little later!"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',8,NULL,'choice','{"stem":"How do people usually imagine a desert island?","options":["As a paradise where fruit falls and no one works","As a frozen land","As a crowded market","As a busy city"],"answer_index":0,"explanation_cn":"课文说 We like to imagine it as a kind of paradise, where the sun always shines, ripe fruit drops…no one ever has to work——人们把荒岛想象成乐园。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',8,NULL,'choice','{"stem":"How did the two men reach the coral island?","options":["They flew in a plane","They swam all the way","They rowed a small rubber dinghy","They walked across ice"],"answer_index":2,"explanation_cn":"课文说 they loaded a small rubber dinghy…and rowed for miles——他们划橡皮小艇到岛上。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',8,NULL,'choice','{"stem":"How did the men feel when they were rescued?","options":["Extremely bored","Angry at each other","Very frightened","Genuinely sorry to leave"],"answer_index":3,"explanation_cn":"课文说 both men were genuinely sorry to leave——获救时两人都由衷地舍不得走。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',9,NULL,'choice','{"stem":"你想说\"我真希望自己会像他们那样捕鱼\"(wish + 过去时,与现在相反):","options":["I wish I knew how to fish like them.","I wish I will know how to fish like them.","I wish I have known how to fish like them.","I wish I know how to fish like them."],"answer_index":0,"explanation_cn":"对现在的愿望(其实不会)用 wish + 过去时 knew。✓ I wish I knew how to fish like them. 场合:但愿现在自己会/有某事(其实没有)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',9,NULL,'choice','{"stem":"你想说\"他们真希望当时在岛上多待些时候\"(wish + 过去完成,对过去):","options":["They wished they have stayed longer on the island.","They wished they stayed longer on the island.","They wished they had stayed longer on the island.","They wished they would stay longer on the island."],"answer_index":2,"explanation_cn":"对过去的愿望用 wish + 过去完成 had stayed。✓ They wished they had stayed longer on the island. 场合:但愿当时做了/多做了某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',9,NULL,'choice','{"stem":"你想说\"如果他们没带鱼枪,就会挨饿\"(与过去相反的虚拟条件):","options":["If they had not brought a spear gun, they will starve.","If they did not bring a spear gun, they would starve.","If they not brought a spear gun, they would have starved.","If they had not brought a spear gun, they would have starved."],"answer_index":3,"explanation_cn":"与过去相反的虚拟:if 从句用过去完成 had not brought,主句用 would have + 过去分词。✓ If they had not brought a spear gun, they would have starved. 场合:假设过去若不是这样,结果会怎样。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"paradise 的意思是:","options":["监狱","地狱","天堂,乐土","沙漠"],"answer_index":2,"explanation_cn":"paradise = 天堂、乐土。✓ a kind of paradise."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"starve 的意思是:","options":["挨饿","大笑","睡觉","唱歌"],"answer_index":0,"explanation_cn":"starve = 挨饿、饿死。✓ may slowly starve."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"\"If I ___ you, I would stay on the island longer.\"(与现在相反:if I ___ you)","options":["am","was","will be","were"],"answer_index":3,"stem_cn":"如果我是你,我会在岛上多待些时候。","explanation_cn":"与现在相反的虚拟里 be 用 were:If I were you…。✓ If I were you, I would stay longer. ✗ am / was / will be:虚拟固定用 were。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"\"The men wished they ___ longer on the island.\"(对过去的愿望:wish + 过去完成)","options":["stay","had stayed","have stayed","stayed"],"answer_index":1,"stem_cn":"那两个人真希望当时在岛上多待些时候。","explanation_cn":"对过去的愿望用 wish + 过去完成 had stayed。✓ The men wished they had stayed longer. ✗ stayed / stay / have stayed:配不出对过去的虚拟愿望。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"\"starve to death\" 的意思是:","options":["冻死","笑死","累死","饿死"],"answer_index":3,"explanation_cn":"starve to death = 饿死。✓ A castaway might starve to death."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"\"quite the opposite\" 的意思是:","options":["截然相反","完全一样","无所谓","差不多"],"answer_index":0,"explanation_cn":"quite the opposite = 截然相反、完全相反。✓ The other side is quite the opposite."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"Why was fresh water not a problem on the island?","options":["They drank seawater","It rained soda","They collected rainwater in the dinghy","There was a deep well"],"answer_index":2,"passage":"Most of us have a very unrealistic picture of life on a desert island. We like to imagine it as a kind of paradise, where the sun always shines, ripe fruit drops from the trees, and no one ever has to work. The other side of the picture is quite the opposite: life on a lonely island can be wretched, and a castaway may slowly starve, like Robinson Crusoe, waiting for a boat that never comes. There is probably an element of truth in both pictures, but few of us ever get the opportunity to find out. Two friends who recently spent five days on a tiny coral island wished they had stayed even longer. They had been sailing a badly damaged boat from the Virgin Islands to Miami to have it repaired when, halfway across, it began to sink. Working fast, they loaded a small rubber dinghy with food, matches, and cans of soda, and rowed for miles across the Caribbean until they reached a coral island. There were almost no trees and no fresh water, but that did not turn out to be a problem: the men caught rainwater in the dinghy. Because they had packed a spear gun, they had plenty to eat. Every day they caught lobster and fish, and, as one of them said, they ''ate like kings.'' When a passing tanker rescued them five days later, both men were genuinely sorry to leave. If that tanker had not come along, who knows how much longer they would have stayed!","explanation_cn":"课文说 the men caught rainwater in the dinghy——他们用橡皮艇接雨水,所以不缺水。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"Why did the men eat so well on the island?","options":["They had brought a spear gun to catch fish","They grew crops fast","They ordered takeout","They found a restaurant"],"answer_index":0,"passage":"Most of us have a very unrealistic picture of life on a desert island. We like to imagine it as a kind of paradise, where the sun always shines, ripe fruit drops from the trees, and no one ever has to work. The other side of the picture is quite the opposite: life on a lonely island can be wretched, and a castaway may slowly starve, like Robinson Crusoe, waiting for a boat that never comes. There is probably an element of truth in both pictures, but few of us ever get the opportunity to find out. Two friends who recently spent five days on a tiny coral island wished they had stayed even longer. They had been sailing a badly damaged boat from the Virgin Islands to Miami to have it repaired when, halfway across, it began to sink. Working fast, they loaded a small rubber dinghy with food, matches, and cans of soda, and rowed for miles across the Caribbean until they reached a coral island. There were almost no trees and no fresh water, but that did not turn out to be a problem: the men caught rainwater in the dinghy. Because they had packed a spear gun, they had plenty to eat. Every day they caught lobster and fish, and, as one of them said, they ''ate like kings.'' When a passing tanker rescued them five days later, both men were genuinely sorry to leave. If that tanker had not come along, who knows how much longer they would have stayed!","explanation_cn":"课文说 Because they had packed a spear gun, they had plenty to eat——带了鱼枪,才能天天捕龙虾和鱼。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"Where were the two men sailing to when their boat sank?","options":["Across the Pacific","From Miami to New York","Around the world","From the Virgin Islands to Miami"],"answer_index":3,"audio":"Most of us have a very unrealistic picture of life on a desert island. We like to imagine it as a kind of paradise, where the sun always shines, ripe fruit drops from the trees, and no one ever has to work. The other side of the picture is quite the opposite: life on a lonely island can be wretched, and a castaway may slowly starve, like Robinson Crusoe, waiting for a boat that never comes. There is probably an element of truth in both pictures, but few of us ever get the opportunity to find out. Two friends who recently spent five days on a tiny coral island wished they had stayed even longer. They had been sailing a badly damaged boat from the Virgin Islands to Miami to have it repaired when, halfway across, it began to sink. Working fast, they loaded a small rubber dinghy with food, matches, and cans of soda, and rowed for miles across the Caribbean until they reached a coral island. There were almost no trees and no fresh water, but that did not turn out to be a problem: the men caught rainwater in the dinghy. Because they had packed a spear gun, they had plenty to eat. Every day they caught lobster and fish, and, as one of them said, they ''ate like kings.'' When a passing tanker rescued them five days later, both men were genuinely sorry to leave. If that tanker had not come along, who knows how much longer they would have stayed!","explanation_cn":"课文说 sailing a badly damaged boat from the Virgin Islands to Miami——他们本要从维尔京群岛开往迈阿密。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l12',10,NULL,'choice','{"stem":"How were the men finally rescued?","options":["A passing tanker picked them up","They swam to Miami","A plane landed on the island","They built a new boat"],"answer_index":0,"audio":"Most of us have a very unrealistic picture of life on a desert island. We like to imagine it as a kind of paradise, where the sun always shines, ripe fruit drops from the trees, and no one ever has to work. The other side of the picture is quite the opposite: life on a lonely island can be wretched, and a castaway may slowly starve, like Robinson Crusoe, waiting for a boat that never comes. There is probably an element of truth in both pictures, but few of us ever get the opportunity to find out. Two friends who recently spent five days on a tiny coral island wished they had stayed even longer. They had been sailing a badly damaged boat from the Virgin Islands to Miami to have it repaired when, halfway across, it began to sink. Working fast, they loaded a small rubber dinghy with food, matches, and cans of soda, and rowed for miles across the Caribbean until they reached a coral island. There were almost no trees and no fresh water, but that did not turn out to be a problem: the men caught rainwater in the dinghy. Because they had packed a spear gun, they had plenty to eat. Every day they caught lobster and fish, and, as one of them said, they ''ate like kings.'' When a passing tanker rescued them five days later, both men were genuinely sorry to leave. If that tanker had not come along, who knows how much longer they would have stayed!","explanation_cn":"课文说 When a passing tanker rescued them five days later——一艘过路油轮救了他们。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l13',3,3,13,'It''s Only Me','是我,别害怕','must 的用法(表推测''一定是'':It must be the baker;表义务''必须'':you must go;以及 mustn''t 表禁止 vs needn''t 表''不必''),外加''形容词 + 动词不定式''结构(glad to hear / eager to try / comfortable to wear / anxious to leave)(原创承载 NCE3 L13 考点·女主人穿鬼装吓跑了抄电表的人)','丈夫上班走后,Porter 太太把孩子们送去学校,匆匆上了楼。那天上午她兴奋得根本干不下家务,因为当晚她要和丈夫去参加化装舞会。她打算扮成幽灵,由于头天晚上就把行头做好了,这会儿急着想试穿。那套“戏服”不过是一条旧白床单,却出奇地有效果。穿好后,她下楼想看看穿着舒不舒服。刚走到餐厅,前门就传来敲门声。“一定是面包师,”她想。她早告诉过他:只要她没去开门,就直接进来,把面包放厨房桌上。她不想吓着这可怜人,便赶紧躲进楼梯下那间小储藏室。她听见前门打开、走廊里响起沉重的脚步。忽然储藏室的门被推开,一个人走了进来。“一定是电力公司来抄电表的,”她意识到。“是我,别害怕,”她轻声想解释——可已经晚了。那人大叫一声,往后蹦了好几步;她一朝他走去,他撒腿就逃,砰地把门带上。','{"q":"Listen and answer — What did the man expect to find under the stairs?","options":["Just a storeroom, not a ghost","A treasure chest","Another door","A sleeping dog"],"answer_index":0}'::jsonb,'{"title":"must 的用法 + 形容词 + 动词不定式","intro":"①must 表“一定是、想必”的推测,对现在很有把握的判断:There''s a knock — it must be the baker(一定是面包师)。②must 表“必须、一定要”的义务:You must finish it first。③注意 mustn''t 是“千万不要、禁止”,needn''t 是“不必、无需”,两者意思不同:You mustn''t open it(不许开)/ You needn''t bring food(不必带)。④“形容词 + 动词不定式”:很多表示情绪、态度的形容词后面直接跟 to + 动词——glad to hear(高兴听到)、eager to try(急着试)、pleased to see(乐见)、anxious to leave(急着走)、comfortable to wear(穿着舒服)。","table":{"headers":["用法","意思","例子"],"rows":[["must + 动词原形(推测)","一定是、想必","It must be the baker."],["must + 动词原形(义务)","必须、一定要","You must finish the costume."],["mustn''t / needn''t","禁止 / 不必","You mustn''t open it. / You needn''t come."],["形容词 + to + 动词","对某事的情绪/态度","glad to hear / eager to try / comfortable to wear"]]},"specialRules":[{"rule":"must 表推测时后面接动词原形,对现在有把握:it must be…;否定推测''不可能是''用 can''t be,不用 mustn''t be。","mark":"must be / can''t be"},{"rule":"mustn''t ≠ needn''t:mustn''t 是''绝不许'',needn''t 是''用不着'';回答 ''Must I…?'' 若否定,常说 ''No, you needn''t.''","mark":"mustn''t / needn''t"},{"rule":"美语里“化装舞会”说 costume party(英式 fancy-dress party);“电表”说 (electricity) meter。本课已按美语写。","mark":"costume party / meter"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l13',1,NULL,'After her husband had left for work, Mrs. Porter sent the kids off to school and hurried upstairs. She was far too excited to do any housework that morning, because that evening she and her husband would be going to a costume party.','丈夫上班走后,Porter 太太把孩子们送去学校,匆匆上了楼。那天上午她兴奋得根本干不下家务,因为当晚她要和丈夫去参加化装舞会。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l13',2,NULL,'She had decided to dress up as a ghost, and since she had made her costume the night before, she was eager to try it on. The costume consisted of nothing but an old white sheet, yet it was surprisingly effective. Once she had it on, Mrs. Porter went downstairs to see whether it would be comfortable to wear.','她打算扮成幽灵,由于头天晚上就把行头做好了,这会儿急着想试穿。那套戏服不过是一条旧白床单,却出奇地有效果。穿好后,她下楼想看看穿着舒不舒服。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l13',3,NULL,'Just as she reached the dining room, there was a knock at the front door. ''It must be the baker,'' she thought. She had told him to come right in whenever she failed to answer, and to leave the bread on the kitchen table.','刚走到餐厅,前门就传来敲门声。“一定是面包师,”她想。她早告诉过他:只要她没去开门,就直接进来,把面包放厨房桌上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l13',4,NULL,'Not wanting to frighten the poor man, she quickly slipped into the little storeroom under the stairs. She heard the door open and heavy footsteps in the hall. Suddenly the storeroom door swung open and a man stepped in. ''He must be the meter reader from the electricity company,'' she realized.','她不想吓着这可怜人,便赶紧躲进楼梯下那间小储藏室。她听见前门打开、走廊里响起沉重的脚步。忽然储藏室的门被推开,一个人走了进来。“一定是电力公司来抄电表的,”她意识到。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l13',5,NULL,'''It''s only me,'' she said gently, trying to explain, but it was too late. The man let out a cry, jumped back several paces, and when she moved toward him, he fled, slamming the door behind him.','“是我,别害怕,”她轻声想解释——可已经晚了。那人大叫一声,往后蹦了好几步;她一朝他走去,他撒腿就逃,砰地把门带上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
