INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l13','closet','wardrobe','壁橱,储物柜;美语 closet,英式 wardrobe') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
