INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l13','dress up as','',NULL,'/dres ʌp æz/','She decided to dress up as a ghost.','她决定扮成幽灵。','The kids dressed up as pirates.','孩子们扮成了海盗。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l13','try on','',NULL,'/traɪ ɑːn/','She was eager to try on her costume.','她急着试穿戏服。','May I try on these shoes?','我可以试穿这双鞋吗?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l13','It''s only me','',NULL,'/ɪts ˈoʊnli miː/','''It''s only me,'' she said gently.','“是我,别害怕,”她轻声说。','Don''t worry — it''s only me.','别担心——是我啦。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l13','let out a cry','',NULL,'/let aʊt ə kraɪ/','The man let out a cry and jumped back.','那人大叫一声,往后一跳。','She let out a cry of surprise.','她惊讶地叫了一声。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp1','choice','{"stem":"\"There''s a knock at the door — it ___ be the baker.\"(表推测“一定是”,用哪个词)","options":["may not","needn''t","must","can"],"answer_index":2,"stem_cn":"有人敲门——一定是面包师。","explanation_cn":"对现在很有把握的推测“一定是”用 must + 动词原形。✓ It must be the baker. ✗ can:表能力/可能,不表这种肯定推测;✗ may not / needn''t:意思相反或不合。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp1','choice','{"stem":"\"Those are heavy footsteps — that ___ be a big man.\"(表推测“一定是”,用哪个词)","options":["must","may not","needn''t","can''t"],"answer_index":0,"stem_cn":"那脚步这么重——一定是个大块头。","explanation_cn":"“脚步这么重,一定是大块头”是肯定推测,用 must。✓ that must be a big man. ✗ can''t:那是“不可能是”;✗ needn''t / may not:不合。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp1','choice','{"stem":"\"She''s wearing a white sheet, so she ___ be dressed as a ghost.\"(表推测“一定是”,用哪个词)","options":["mustn''t","can","must","needn''t"],"answer_index":2,"stem_cn":"她披着白床单,一定是扮成了幽灵。","explanation_cn":"“披着白床单,一定是扮鬼”是肯定推测,用 must。✓ she must be dressed as a ghost. ✗ mustn''t 禁止;✗ needn''t 不必;✗ can 不表这种推测。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp2','choice','{"stem":"\"If you want to go to the party, you ___ finish the costume first.\"(表示“必须”,用哪个词)","options":["could","must","mustn''t","needn''t"],"answer_index":1,"stem_cn":"想去舞会,你就得先把戏服做好。","explanation_cn":"表示“必须、一定要”用 must。✓ you must finish the costume first. ✗ needn''t 不必;✗ mustn''t 禁止;✗ could 表示可能/委婉。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp2','choice','{"stem":"\"Guests ___ arrive before eight, or the doors will be locked.\"(表示“必须”,用哪个词)","options":["needn''t","may not","could","must"],"answer_index":3,"stem_cn":"客人必须八点前到,否则门就锁了。","explanation_cn":"“必须八点前到”表义务,用 must。✓ Guests must arrive before eight. ✗ needn''t 不必;✗ may not 不许;✗ could 不表强制。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp3','choice','{"stem":"\"You ___ open that door — there''s a surprise behind it!\"(表示“禁止、不许”,用哪个词)","options":["needn''t","may","mustn''t","must"],"answer_index":2,"stem_cn":"你不许打开那扇门——后面有惊喜!","explanation_cn":"“千万别、不许”用 mustn''t。✓ You mustn''t open that door. ✗ needn''t 是“不必”,意思不同;✗ must 是“必须”;✗ may 是“可以”。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp3','choice','{"stem":"\"You ___ bring any food; everything is already prepared.\"(表示“不必、无需”,用哪个词)","options":["should","mustn''t","must","needn''t"],"answer_index":3,"stem_cn":"你不用带吃的,一切都备好了。","explanation_cn":"“不必、无需”用 needn''t。✓ You needn''t bring any food. ✗ mustn''t 是“禁止”,意思相反;✗ must 必须;✗ should 应该。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp3','choice','{"stem":"\"We ___ make noise here; the baby is sleeping.\"(表示“禁止、不许”,用哪个词)","options":["can","may","mustn''t","needn''t"],"answer_index":2,"stem_cn":"这里不许吵,宝宝在睡觉。","explanation_cn":"“不许吵”用 mustn''t。✓ We mustn''t make noise here. ✗ needn''t 不必;✗ may / can 是“可以”。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp4','choice','{"stem":"\"I was glad ___ that you feel better now.\"(形容词后接动词不定式)","options":["to hear","hear","hearing","heard"],"answer_index":0,"stem_cn":"听到你现在好些了,我很高兴。","explanation_cn":"形容词 glad 后面接“to + 动词”:glad to hear。✓ I was glad to hear that… ✗ hearing / hear / heard:glad 后要用动词不定式 to hear。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp4','choice','{"stem":"\"The children were delighted ___ the funny costume.\"(形容词后接动词不定式)","options":["see","saw","seeing","to see"],"answer_index":3,"stem_cn":"孩子们见到那滑稽的戏服都乐坏了。","explanation_cn":"形容词 delighted 后面接“to + 动词”:delighted to see。✓ delighted to see the costume. ✗ seeing / see / saw:要用 to see。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp4','choice','{"stem":"\"He was anxious ___ the party early because of the storm.\"(形容词后接动词不定式)","options":["left","to leave","leave","leaving"],"answer_index":1,"stem_cn":"因为暴风雨,他急着早点离开舞会。","explanation_cn":"形容词 anxious 后面接“to + 动词”:anxious to leave(急着走)。✓ anxious to leave early. ✗ leaving / leave / left:要用 to leave。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp5','choice','{"stem":"\"Mrs. Porter was too excited ___ any housework that morning.\"(“太……以致不能……”后接不定式)","options":["do","did","to do","doing"],"answer_index":2,"stem_cn":"那天上午 Porter 太太兴奋得干不下家务。","explanation_cn":"“too + 形容词 + to + 动词”表示“太……以致不能……”:too excited to do。✓ too excited to do any housework. ✗ doing / do / did:这个结构里要用 to do。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp5','choice','{"stem":"\"The ghost costume was not very comfortable ___.\"(形容词 comfortable 后接动词不定式)","options":["worn","to wear","wear","wearing"],"answer_index":1,"stem_cn":"那套幽灵戏服穿着不太舒服。","explanation_cn":"形容词 comfortable 后接“to + 动词”:comfortable to wear(穿着舒服)。✓ comfortable to wear. ✗ wearing / wear / worn:要用 to wear。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp5','choice','{"stem":"\"She was proud ___ the whole costume by herself.\"(形容词 proud 后接动词不定式)","options":["to make","making","made","make"],"answer_index":0,"stem_cn":"她为自己独力做出整套戏服而自豪。","explanation_cn":"形容词 proud 后接“to + 动词”:proud to make。✓ proud to make the whole costume. ✗ making / make / made:要用 to make。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp6','choice','{"stem":"\"A small room used for storing things is a ___.\"(“储藏室”用哪个词)","options":["bedroom","storeroom","classroom","bathroom"],"answer_index":1,"stem_cn":"用来放东西的小房间是储藏室。","explanation_cn":"专门用来放东西的小房间是 storeroom(储藏室)。✓ the storeroom under the stairs. ✗ bathroom 浴室;✗ classroom 教室;✗ bedroom 卧室——都不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp6','choice','{"stem":"\"To run away in fear is to ___.\"(“逃走”用哪个词)","options":["cook","sing","flee","dance"],"answer_index":2,"stem_cn":"因害怕而跑开就是逃走。","explanation_cn":"因害怕而跑开、逃走用 flee(过去式 fled)。✓ he fled in fear. ✗ dance 跳舞;✗ cook 做饭;✗ sing 唱歌——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp6','choice','{"stem":"\"To shut a door hard and loudly is to ___ it.\"(“砰地关上”用哪个词)","options":["slam","lock","wash","paint"],"answer_index":0,"stem_cn":"使劲砰地关门就是 slam。","explanation_cn":"使劲、砰的一声关门用 slam。✓ slam the door. ✗ paint 刷漆;✗ lock 上锁;✗ wash 洗——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',5,'am3_l13_gp6','choice','{"stem":"\"The clothes you wear to look like someone else at a party is a ___.\"(“化装服”用哪个词)","options":["ticket","mirror","costume","basket"],"answer_index":2,"stem_cn":"舞会上为扮成别人而穿的衣服是化装服。","explanation_cn":"为在舞会上扮成别人而穿的衣服是 costume(化装服)。✓ a ghost costume. ✗ ticket 票;✗ mirror 镜子;✗ basket 篮子——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',6,NULL,'choice','{"stem":"costume 的意思是:","options":["睡衣","化装服,戏服","泳衣","制服"],"answer_index":1,"explanation_cn":"costume = 化装服、戏服。✓ a ghost costume 幽灵戏服。\n顺带记:制服 = uniform;睡衣 = pajamas;泳衣 = swimsuit."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',6,NULL,'choice','{"stem":"effective 的意思是:","options":["昂贵的","无用的","破旧的","有明显效果的,有作用的"],"answer_index":3,"explanation_cn":"effective = 有明显效果的、管用的。✓ surprisingly effective 出奇地有效果。\n顺带记:无用的 = useless;昂贵的 = expensive;破旧的 = shabby."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',6,NULL,'choice','{"stem":"flee 的意思是:","options":["唱歌","睡觉","逃走","大笑"],"answer_index":2,"explanation_cn":"flee = 逃走(过去式 fled)。✓ he fled 他逃走了。\n顺带记:大笑 = laugh;睡觉 = sleep;唱歌 = sing."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',6,NULL,'choice','{"stem":"comfortable 的意思是:","options":["危险的","吵闹的","昂贵的","舒适的"],"answer_index":3,"explanation_cn":"comfortable = 舒适的。✓ comfortable to wear 穿着舒服。\n顺带记:危险的 = dangerous;吵闹的 = noisy;昂贵的 = expensive."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',6,NULL,'choice','{"stem":"\"storeroom\" 的意思是:","options":["卧室","厨房","储藏室","阳台"],"answer_index":2,"explanation_cn":"storeroom = 储藏室(放东西的小房间)。✓ the storeroom under the stairs 楼梯下的储藏室。\n顺带记:卧室 = bedroom;厨房 = kitchen;阳台 = balcony."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',6,NULL,'choice','{"stem":"consist 的意思是:","options":["由……组成","隐藏","打碎","拒绝"],"answer_index":0,"explanation_cn":"consist = 由……组成(consist of)。✓ consist of a sheet 由一条床单组成。\n顺带记:拒绝 = refuse;隐藏 = hide;打碎 = break."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',7,NULL,'cloze','{"stem":"第 1 空","context":"Mrs. Porter was eager ___1___ on her ghost costume. When someone knocked, she thought, ''It ___2___ be the baker.'' She hid in the storeroom. Then the door opened, and she realized it ___3___ be the meter reader. ''It''s only me,'' she said, glad ___4___ him, but the frightened man fled.","blank_no":1,"options":["trying","to try","try","tried"],"answer_index":1,"explanation_cn":"形容词 eager 后接“to + 动词”:eager to try。✓ eager to try on her costume."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',7,NULL,'cloze','{"stem":"第 2 空","context":"Mrs. Porter was eager ___1___ on her ghost costume. When someone knocked, she thought, ''It ___2___ be the baker.'' She hid in the storeroom. Then the door opened, and she realized it ___3___ be the meter reader. ''It''s only me,'' she said, glad ___4___ him, but the frightened man fled.","blank_no":2,"options":["can","must","should","need"],"answer_index":1,"explanation_cn":"对现在的肯定推测“一定是”用 must。✓ It must be the baker."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',7,NULL,'cloze','{"stem":"第 3 空","context":"Mrs. Porter was eager ___1___ on her ghost costume. When someone knocked, she thought, ''It ___2___ be the baker.'' She hid in the storeroom. Then the door opened, and she realized it ___3___ be the meter reader. ''It''s only me,'' she said, glad ___4___ him, but the frightened man fled.","blank_no":3,"options":["must","mustn''t","needn''t","may not"],"answer_index":0,"explanation_cn":"“一定是抄电表的”是肯定推测,用 must。✓ it must be the meter reader."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',7,NULL,'cloze','{"stem":"第 4 空","context":"Mrs. Porter was eager ___1___ on her ghost costume. When someone knocked, she thought, ''It ___2___ be the baker.'' She hid in the storeroom. Then the door opened, and she realized it ___3___ be the meter reader. ''It''s only me,'' she said, glad ___4___ him, but the frightened man fled.","blank_no":4,"options":["to see","seeing","see","saw"],"answer_index":0,"explanation_cn":"形容词 glad 后接“to + 动词”:glad to see。✓ glad to see him."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',8,NULL,'choice','{"stem":"Why was Mrs. Porter so excited that morning?","options":["It was her birthday","She was going to a costume party that evening","She had won a prize","Her children were home"],"answer_index":1,"explanation_cn":"课文说 that evening she and her husband would be going to a costume party——她因当晚要去化装舞会而兴奋。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',8,NULL,'choice','{"stem":"What was her ghost costume made of?","options":["A blanket and a hat","A raincoat","An old white sheet","A cardboard box"],"answer_index":2,"explanation_cn":"课文说 The costume consisted of nothing but an old white sheet——戏服就是一条旧白床单。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',8,NULL,'choice','{"stem":"Why did the meter reader run away?","options":["He disliked the house","He forgot his tools","He was late for work","He thought the costume was a real ghost"],"answer_index":3,"explanation_cn":"课文说她穿着白床单说“It''s only me”,那人却大叫逃走——他把戏服当成了真幽灵。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',9,NULL,'choice','{"stem":"你想说\"敲门的一定是面包师\"(must 表推测):","options":["It can be the baker at the door.","It must be the baker at the door.","It needn''t be the baker at the door.","It must to be the baker at the door."],"answer_index":1,"explanation_cn":"对现在的肯定推测“一定是”用 must + 动词原形 be。✓ It must be the baker at the door. 场合:根据线索有把握地判断“一定是……”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',9,NULL,'choice','{"stem":"你想说\"我很高兴听到你好些了\"(形容词 + 动词不定式):","options":["I am glad to hear that you feel better.","I am glad hearing that you feel better.","I am glad that to hear you feel better.","I am glad hear that you feel better."],"answer_index":0,"explanation_cn":"形容词 glad 后接“to + 动词”:glad to hear。✓ I am glad to hear that you feel better. 场合:表达对某事的高兴/情绪,后接不定式。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',9,NULL,'choice','{"stem":"你想说\"你不许打开那扇门\"(mustn''t 表禁止):","options":["You needn''t open that door.","You don''t must open that door.","You mustn''t open that door.","You mustn''t to open that door."],"answer_index":2,"explanation_cn":"“千万别、不许”用 mustn''t + 动词原形。✓ You mustn''t open that door. 场合:强烈禁止某人做某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"costume 的意思是:","options":["睡衣","制服","化装服,戏服","泳衣"],"answer_index":2,"explanation_cn":"costume = 化装服、戏服。✓ a ghost costume."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"flee 的意思是:","options":["大笑","逃走","睡觉","唱歌"],"answer_index":1,"explanation_cn":"flee = 逃走(fled)。✓ he fled."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"\"There''s a knock — it ___ be the baker.\"(表推测“一定是”)","options":["can","needn''t","may not","must"],"answer_index":3,"stem_cn":"有人敲门——一定是面包师。","explanation_cn":"对现在的肯定推测“一定是”用 must。✓ it must be the baker. ✗ can / needn''t / may not:都不表这种肯定推测。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"\"I was glad ___ that you feel better.\"(形容词后接动词不定式)","options":["heard","to hear","hearing","hear"],"answer_index":1,"stem_cn":"听到你好些了,我很高兴。","explanation_cn":"形容词 glad 后接“to + 动词”:glad to hear。✓ I was glad to hear that… ✗ hearing / hear / heard:要用 to hear。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"\"dress up as\" 的意思是:","options":["洗净…","脱下…","化装成…","叠好…"],"answer_index":2,"explanation_cn":"dress up as = 化装成、打扮成……。✓ dress up as a ghost 扮成幽灵。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"\"let out a cry\" 的意思是:","options":["保持安静","发出一声叫喊","小声说话","轻声哼唱"],"answer_index":1,"explanation_cn":"let out a cry = 发出一声叫喊。✓ The man let out a cry 那人大叫一声。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"Why did Mrs. Porter hide in the storeroom?","options":["She did not want to frighten the baker","She was cold","She was playing hide-and-seek","She heard a thief"],"answer_index":0,"passage":"After her husband had left for work, Mrs. Porter sent the kids off to school and hurried upstairs. She was far too excited to do any housework that morning, because that evening she and her husband would be going to a costume party. She had decided to dress up as a ghost, and since she had made her costume the night before, she was eager to try it on. The costume consisted of nothing but an old white sheet, yet it was surprisingly effective. Once she had it on, Mrs. Porter went downstairs to see whether it would be comfortable to wear. Just as she reached the dining room, there was a knock at the front door. ''It must be the baker,'' she thought. She had told him to come right in whenever she failed to answer, and to leave the bread on the kitchen table. Not wanting to frighten the poor man, she quickly slipped into the little storeroom under the stairs. She heard the door open and heavy footsteps in the hall. Suddenly the storeroom door swung open and a man stepped in. ''He must be the meter reader from the electricity company,'' she realized. ''It''s only me,'' she said gently, trying to explain, but it was too late. The man let out a cry, jumped back several paces, and when she moved toward him, he fled, slamming the door behind him.","explanation_cn":"课文说 Not wanting to frighten the poor man, she quickly slipped into the storeroom——她躲起来是怕吓着(以为是)面包师的人。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"What did Mrs. Porter say to the man in the storeroom?","options":["Nothing at all","''Get out!''","''It''s only me''","''Help me!''"],"answer_index":2,"passage":"After her husband had left for work, Mrs. Porter sent the kids off to school and hurried upstairs. She was far too excited to do any housework that morning, because that evening she and her husband would be going to a costume party. She had decided to dress up as a ghost, and since she had made her costume the night before, she was eager to try it on. The costume consisted of nothing but an old white sheet, yet it was surprisingly effective. Once she had it on, Mrs. Porter went downstairs to see whether it would be comfortable to wear. Just as she reached the dining room, there was a knock at the front door. ''It must be the baker,'' she thought. She had told him to come right in whenever she failed to answer, and to leave the bread on the kitchen table. Not wanting to frighten the poor man, she quickly slipped into the little storeroom under the stairs. She heard the door open and heavy footsteps in the hall. Suddenly the storeroom door swung open and a man stepped in. ''He must be the meter reader from the electricity company,'' she realized. ''It''s only me,'' she said gently, trying to explain, but it was too late. The man let out a cry, jumped back several paces, and when she moved toward him, he fled, slamming the door behind him.","explanation_cn":"课文说 ''It''s only me,'' she said gently——她对那人说的是“是我,别害怕”。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"What did the man expect to find when he opened the storeroom?","options":["A sleeping dog","Just a storeroom, not a ghost","Another exit","A treasure chest"],"answer_index":1,"audio":"After her husband had left for work, Mrs. Porter sent the kids off to school and hurried upstairs. She was far too excited to do any housework that morning, because that evening she and her husband would be going to a costume party. She had decided to dress up as a ghost, and since she had made her costume the night before, she was eager to try it on. The costume consisted of nothing but an old white sheet, yet it was surprisingly effective. Once she had it on, Mrs. Porter went downstairs to see whether it would be comfortable to wear. Just as she reached the dining room, there was a knock at the front door. ''It must be the baker,'' she thought. She had told him to come right in whenever she failed to answer, and to leave the bread on the kitchen table. Not wanting to frighten the poor man, she quickly slipped into the little storeroom under the stairs. She heard the door open and heavy footsteps in the hall. Suddenly the storeroom door swung open and a man stepped in. ''He must be the meter reader from the electricity company,'' she realized. ''It''s only me,'' she said gently, trying to explain, but it was too late. The man let out a cry, jumped back several paces, and when she moved toward him, he fled, slamming the door behind him.","explanation_cn":"抄表人打开楼梯下的门,本以为是普通储藏室,没想到里面站着个“幽灵”。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l13',10,NULL,'choice','{"stem":"What did the man do after seeing the ''ghost''?","options":["He fainted","He took a photo","He laughed loudly","He fled, slamming the door"],"answer_index":3,"audio":"After her husband had left for work, Mrs. Porter sent the kids off to school and hurried upstairs. She was far too excited to do any housework that morning, because that evening she and her husband would be going to a costume party. She had decided to dress up as a ghost, and since she had made her costume the night before, she was eager to try it on. The costume consisted of nothing but an old white sheet, yet it was surprisingly effective. Once she had it on, Mrs. Porter went downstairs to see whether it would be comfortable to wear. Just as she reached the dining room, there was a knock at the front door. ''It must be the baker,'' she thought. She had told him to come right in whenever she failed to answer, and to leave the bread on the kitchen table. Not wanting to frighten the poor man, she quickly slipped into the little storeroom under the stairs. She heard the door open and heavy footsteps in the hall. Suddenly the storeroom door swung open and a man stepped in. ''He must be the meter reader from the electricity company,'' she realized. ''It''s only me,'' she said gently, trying to explain, but it was too late. The man let out a cry, jumped back several paces, and when she moved toward him, he fled, slamming the door behind him.","explanation_cn":"课文说 he fled, slamming the door behind him——他撒腿就逃,砰地把门带上。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l14',3,3,14,'He''d Rather Do It Himself','他宁愿自己动手','would rather / would sooner 表“宁愿、偏好”(would rather do / would sooner do / would rather ... than ... / would rather + 某人 + 过去式:I''d rather you watched),外加 have sth done“(请人)把某事做好”与 have + 动作名词(have a look)(原创承载 NCE3 L14 考点·净化:把“贵族歹徒勒索保护费”改写为“宁愿凡事亲力亲为的传奇手艺人 Dawson”,保留“被全镇敬重、立牌纪念”的反差,去掉一切犯罪暴力)','小镇上人人都认识老 Dawson——一个了不起的手艺人。他宁愿自己动手修理一切,也不愿请别人代劳。一场冬天的暴风雨毁掉了他家一段篱笆,邻居们提出替他从城里雇一队工人,他只是笑笑:“我宁愿自己亲手来。”一周之内,整段篱笆又立了起来。镇上大多数人都请公司来修屋顶、修车、翻院子,唯独 Dawson 不肯。他宁愿在漏水的水龙头下待整整一个下午,也不愿打电话叫水管工;宁愿步行五英里,也不愿让人开车送他。每天清早他都爱把工具挨个看一遍,宁愿打着手电干到深夜,也绝不把活儿干一半就撂下。若有小伙子想帮忙,他会和气地说:“我更愿意你在一旁看着学。”谁要不打招呼就拿走他心爱的扳手,他会说:“我希望你别这样。”他做事又快又利落,却分文不取。等他终于老得爬不动梯子,全镇人聚到一起;他去世后,大家在镇政府旁立了一块小铜牌,纪念这位“谁也想不起还有更顽强”的手艺人。乐队奏起乐来,人人都说:宁愿认识一个 Dawson,也胜过认识一百个名人。','{"q":"Listen and answer — Why wouldn''t Old Mr. Dawson let others repair his fence?","options":["He would rather do everything himself","He had no fence","He was too busy that week","He lived far from town"],"answer_index":0}'::jsonb,'{"title":"would rather / would sooner 偏好 + have sth done","intro":"①would rather / would sooner + 动词原形,表示“宁愿做某事”:I would rather stay(我宁愿留下)。②“宁愿做 A 不愿做 B”用 would rather A than B:He would rather walk than wait(他宁愿走也不愿等)。③否定用 would rather not + 原形:I would rather not go。④若“希望别人怎么做”,用 would rather + 某人 + 过去式动词:I''d rather you watched and learned(我更愿意你看着学)/ I''d rather you didn''t touch it(我希望你别碰)。⑤have sth done 表示“(请/让别人)把某事做好”:have the roof repaired(请人修屋顶);have + 动作名词表示“做一次”:have a look(看一看)、have a rest(歇一歇)。","table":{"headers":["用法","意思","例子"],"rows":[["would rather / would sooner + 原形","宁愿做……","I''d rather stay. / I''d sooner walk."],["would rather A than B","宁愿 A 不愿 B","He would rather fix it than pay someone."],["would rather + 某人 + 过去式","希望某人怎样(现在/将来)","I''d rather you watched. / I''d rather you didn''t."],["have sth done / have a look","请人把某事做好 / 做一次","have the roof repaired / have a look"]]},"specialRules":[{"rule":"would rather / would sooner 后面接动词原形(不带 to):I''d rather go(✓)/ I''d rather to go(✗)。","mark":"would rather + 原形"},{"rule":"“希望别人”时用 would rather + 某人 + 过去式:I''d rather you came early;否定 I''d rather you didn''t。这里的过去式不表示过去,而表示委婉的愿望。","mark":"I''d rather you came"},{"rule":"have sth done = 请/让别人做:have your car fixed(让人修车)≠ 自己修;宾位放在 have 和过去分词之间。美语里“水龙头”说 faucet(英式 tap),“手电筒”说 flashlight(英式 torch)。","mark":"have sth done / faucet"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l14',1,NULL,'Everyone in our little town knew Old Mr. Dawson, a remarkable handyman who would rather fix a thing himself than have it done by anyone else. When a winter storm destroyed part of his fence, his neighbors offered to hire a crew from the city, but Dawson only smiled.','小镇上人人都认识老 Dawson——一个了不起的手艺人,他宁愿自己动手修理一切,也不愿请别人代劳。一场冬天的暴风雨毁掉了他家一段篱笆,邻居们提出替他从城里雇一队工人,他只是笑笑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l14',2,NULL,'''I''d sooner do it with my own two hands,'' he said, and he had the whole fence standing again within a week. Most people in town would have their roofs repaired, their cars fixed, and their yards dug by companies. Not Dawson.','“我宁愿自己亲手来,”他说。一周之内,整段篱笆又立了起来。镇上大多数人都请公司来修屋顶、修车、翻院子,唯独 Dawson 不肯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l14',3,NULL,'He would rather spend a whole afternoon under a leaking faucet than call a plumber, and he would sooner walk five miles than have someone drive him. Each morning he liked to have a good look at his tools, and he''d rather work late by flashlight than leave a job half done.','他宁愿在漏水的水龙头下待整整一个下午,也不愿打电话叫水管工;宁愿步行五英里,也不愿让人开车送他。每天清早他都爱把工具挨个看一遍,宁愿打着手电干到深夜,也绝不把活儿干一半就撂下。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l14',4,NULL,'If a young man offered to help, Dawson would say kindly, ''I''d rather you watched and learned.'' And if anyone picked up his favorite wrench without asking, he''d say, ''I''d rather you didn''t.'' He fixed everything promptly and never charged a cent.','若有小伙子想帮忙,他会和气地说:“我更愿意你在一旁看着学。”谁要不打招呼就拿走他心爱的扳手,他会说:“我希望你别这样。”他做事又快又利落,却分文不取。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l14',5,NULL,'When at last he grew too old to climb ladders, the whole town came together, and after his funeral they dedicated a small brass plaque by the town hall to the memory of the most valiant handyman anyone could remember. A band played, and everyone agreed that they would rather have known one Mr. Dawson than a hundred famous men.','等他终于老得爬不动梯子,全镇人聚到一起;他去世后,大家在镇政府旁立了一块小铜牌,纪念这位“谁也想不起还有更顽强”的手艺人。乐队奏起乐来,人人都说:宁愿认识一个 Dawson,也胜过认识一百个名人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
