INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l14','would rather ... than ...','',NULL,'/wʊd ˈræðər ... ðæn/','He would rather fix it himself than pay someone.','他宁愿自己修,也不愿花钱雇人。','I''d rather stay in than go out tonight.','今晚我宁愿待在家里,也不想出门。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l14','would sooner','',NULL,'/wʊd ˈsuːnər/','I''d sooner walk than wait for a ride.','我宁愿走路,也不愿等人来接。','She''d sooner do it herself.','她宁愿自己来做。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l14','have sth done','',NULL,'/hæv ˈsʌmθɪŋ dʌn/','They have their roof repaired every spring.','他们每年春天都请人修屋顶。','I had my car fixed yesterday.','我昨天把车送去修了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l14','with one''s own two hands','',NULL,'/wɪð wʌnz oʊn tuː hændz/','He built the fence with his own two hands.','他亲手把篱笆搭了起来。','I made this with my own two hands.','这是我亲手做的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp1','choice','{"stem":"\"He would rather ___ the fence himself than pay a crew.\"(would rather 后接动词原形)","options":["to fix","fix","fixing","fixed"],"answer_index":1,"stem_cn":"他宁愿自己修篱笆,也不愿雇人。","explanation_cn":"would rather 后面接动词原形(不带 to):would rather fix。✓ He would rather fix the fence himself. ✗ to fix / fixing / fixed:would rather 后要用原形。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp1','choice','{"stem":"\"I''d rather ___ it with my own two hands.\"(would rather 后接动词原形)","options":["to do","doing","do","did"],"answer_index":2,"stem_cn":"我宁愿自己亲手来做。","explanation_cn":"would rather 后接动词原形:would rather do。✓ I''d rather do it with my own two hands. ✗ to do / doing / did:要用原形。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp1','choice','{"stem":"\"She would rather ___ at home than go to the party.\"(would rather 后接动词原形)","options":["stay","stayed","to stay","staying"],"answer_index":0,"stem_cn":"她宁愿待在家里,也不去参加聚会。","explanation_cn":"would rather 后接动词原形:would rather stay。✓ She would rather stay at home. ✗ to stay / staying / stayed:要用原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp2','choice','{"stem":"\"Tonight I would rather ___ go out at all.\"(表示“宁愿不……”)","options":["no","not","not to","don''t"],"answer_index":1,"stem_cn":"今晚我宁愿根本不出门。","explanation_cn":"“宁愿不做”用 would rather not + 原形:would rather not go。✓ I would rather not go out at all. ✗ don''t / not to / no:would rather 的否定直接加 not。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp2','choice','{"stem":"\"He would rather walk five miles ___ take the bus.\"(“宁愿 A 不愿 B”)","options":["then","that","to","than"],"answer_index":3,"stem_cn":"他宁愿走五英里,也不愿坐公交。","explanation_cn":"“宁愿 A 不愿 B”用 would rather A than B。✓ walk five miles than take the bus. ✗ then(那时)/ that / to:表“而不愿”要用 than。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp2','choice','{"stem":"\"Dawson would rather work all day than ___ someone else do it.\"(than 后接动词原形)","options":["has","to have","have","having"],"answer_index":2,"stem_cn":"Dawson 宁愿干一整天,也不愿让别人来做。","explanation_cn":"than 后面同样接动词原形:than have someone else do it。✓ would rather work all day than have someone else do it. ✗ to have / having / has:要用原形 have。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp3','choice','{"stem":"\"I''d ___ do it myself.\"(与 would rather 同义的“宁愿”)","options":["sooner","sooner than","more soon","soon"],"answer_index":0,"stem_cn":"我宁愿自己做。","explanation_cn":"would sooner = would rather,同样表示“宁愿”。✓ I''d sooner do it myself. ✗ soon / sooner than / more soon:固定说 would sooner。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp3','choice','{"stem":"\"He would sooner walk ___ wait for a ride.\"(“宁愿 A 不愿 B”)","options":["as","then","than","that"],"answer_index":2,"stem_cn":"他宁愿走路,也不愿等人来接。","explanation_cn":"would sooner A than B,和 would rather 一样用 than。✓ walk than wait for a ride. ✗ then / that / as:表“而不愿”要用 than。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp3','choice','{"stem":"\"She would sooner ___ late than leave a job half done.\"(would sooner 后接动词原形)","options":["to work","work","working","worked"],"answer_index":1,"stem_cn":"她宁愿加班到很晚,也不愿把活儿干一半。","explanation_cn":"would sooner 后接动词原形:would sooner work。✓ She would sooner work late. ✗ to work / working / worked:要用原形。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp4','choice','{"stem":"\"Dawson would rather you ___ his tools alone.\"(would rather + 某人 + 过去式)","options":["to leave","leave","left","leaving"],"answer_index":2,"stem_cn":"Dawson 希望你别动他的工具。","explanation_cn":"“希望某人怎样”用 would rather + 某人 + 过去式,这里的过去式表委婉愿望而非过去:would rather you left。✓ Dawson would rather you left his tools alone. ✗ leave / to leave / leaving:这个句式里要用过去式 left。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp4','choice','{"stem":"\"''I''d rather you ___ and learned,'' he said.\"(would rather + 某人 + 过去式)","options":["watched","watch","watching","to watch"],"answer_index":0,"stem_cn":"“我更愿意你在旁边看着学,”他说。","explanation_cn":"would rather + 某人 + 过去式:would rather you watched。✓ I''d rather you watched and learned. ✗ watch / to watch / watching:要用过去式 watched(和后面 learned 一致)。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp4','choice','{"stem":"\"I''d rather you ___ that wrench without asking.\"(would rather + 某人,否定用过去式)","options":["weren''t touch","not touch","don''t touch","didn''t touch"],"answer_index":3,"stem_cn":"我希望你别不打招呼就动那把扳手。","explanation_cn":"would rather + 某人 的否定,用过去式否定 didn''t do。✓ I''d rather you didn''t touch that wrench. ✗ don''t touch / not touch / weren''t touch:这个句式否定用 didn''t touch。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp5','choice','{"stem":"\"Most people have their roofs ___ by a company.\"(have sth done,用过去分词)","options":["repaired","repair","repairing","to repair"],"answer_index":0,"stem_cn":"大多数人请公司来修屋顶。","explanation_cn":"have sth done“(请人)把某事做好”,done 用过去分词:have their roofs repaired。✓ Most people have their roofs repaired. ✗ repair / repairing / to repair:have + 名词后要用过去分词 repaired。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp5','choice','{"stem":"\"They had their cars ___ at the city garage.\"(have sth done,用过去分词)","options":["fix","fixed","to fix","fixing"],"answer_index":1,"stem_cn":"他们把车送到城里的修车行去修。","explanation_cn":"have sth done,用过去分词:have their cars fixed。✓ They had their cars fixed at the garage. ✗ fix / fixing / to fix:要用过去分词 fixed。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp5','choice','{"stem":"\"Each morning he liked to have a ___ at his tools.\"(have a ___ = 看一看)","options":["seeing","sight","watching","look"],"answer_index":3,"stem_cn":"每天早上他都爱看看他的工具。","explanation_cn":"have a look = 看一看(have + 动作名词表示“做一次”)。✓ have a good look at his tools. ✗ seeing / watching / sight:固定搭配是 have a look。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp6','choice','{"stem":"\"A person who is good at fixing many small things around a house is a ___.\"(“杂修工”用哪个词)","options":["singer","handyman","driver","dancer"],"answer_index":1,"stem_cn":"擅长修理家里各种小东西的人。","explanation_cn":"擅长修理家里各种小东西的人是 handyman(杂修工)。✓ a remarkable handyman. ✗ dancer 舞者;✗ singer 歌手;✗ driver 司机——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp6','choice','{"stem":"\"To break something completely is to ___ it.\"(“毁坏”用哪个词)","options":["destroy","wash","paint","borrow"],"answer_index":0,"stem_cn":"把某物彻底破坏就是这个词。","explanation_cn":"把某物彻底破坏用 destroy(毁坏)。✓ a storm destroyed the fence. ✗ wash 洗;✗ paint 刷漆;✗ borrow 借——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',5,'am3_l14_gp6','choice','{"stem":"\"The fixture that controls water at a sink is a ___.\"(美语“水龙头”用哪个词)","options":["mirror","faucet","basket","ladder"],"answer_index":1,"stem_cn":"水槽上控制水流的装置(美语)。","explanation_cn":"美语里水槽上控制水流的装置是 faucet(水龙头;英式 tap)。✓ a leaking faucet. ✗ ladder 梯子;✗ basket 篮子;✗ mirror 镜子——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',6,NULL,'choice','{"stem":"remarkable 的意思是:","options":["普通的","害怕的","非凡的,了不起的","便宜的"],"answer_index":2,"explanation_cn":"remarkable = 非凡的、了不起的。✓ a remarkable handyman 了不起的手艺人。\n顺带记:普通的 = ordinary;害怕的 = afraid;便宜的 = cheap."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',6,NULL,'choice','{"stem":"hire 的意思是:","options":["雇用","解雇","购买","借给"],"answer_index":0,"explanation_cn":"hire = 雇用。✓ hire a crew 雇一队工人。\n顺带记:解雇 = fire;购买 = buy;借给 = lend."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',6,NULL,'choice','{"stem":"promptly 的意思是:","options":["大声地","偶然地","迅速地,及时地","缓慢地"],"answer_index":2,"explanation_cn":"promptly = 迅速地、及时地。✓ fixed everything promptly 什么都修得又快又利落。\n顺带记:缓慢地 = slowly;偶然地 = accidentally;大声地 = loudly."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',6,NULL,'choice','{"stem":"valiant 的意思是:","options":["英勇的,顽强的","富有的","懒惰的","胆小的"],"answer_index":0,"explanation_cn":"valiant = 英勇的、顽强的。✓ the most valiant handyman 最顽强的手艺人。\n顺带记:胆小的 = timid;懒惰的 = lazy;富有的 = rich."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',6,NULL,'choice','{"stem":"dedicate 的意思是:","options":["出售","隐藏","拆除","献给,题献"],"answer_index":3,"explanation_cn":"dedicate = 献给、题献(为……立碑/牌)。✓ dedicated a plaque to his memory 立牌纪念他。\n顺带记:拆除 = demolish;隐藏 = hide;出售 = sell."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',6,NULL,'choice','{"stem":"plumber 的意思是:","options":["教师","医生","管道工,水管工","厨师"],"answer_index":2,"explanation_cn":"plumber = 管道工、水管工。✓ call a plumber 叫水管工。\n顺带记:医生 = doctor;教师 = teacher;厨师 = cook."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',7,NULL,'cloze','{"stem":"第 1 空","context":"Old Mr. Dawson would rather ___1___ everything himself. When a storm destroyed his fence, he would sooner rebuild it ___2___ hire a crew. Unlike his neighbors, who had their roofs ___3___ by companies, Dawson worked with his own hands. ''I''d rather you ___4___ my tools alone,'' he''d tell the young helpers with a smile.","blank_no":1,"options":["fix","to fix","fixing","fixed"],"answer_index":0,"explanation_cn":"would rather 后接动词原形:would rather fix。✓ Dawson would rather fix everything himself."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',7,NULL,'cloze','{"stem":"第 2 空","context":"Old Mr. Dawson would rather ___1___ everything himself. When a storm destroyed his fence, he would sooner rebuild it ___2___ hire a crew. Unlike his neighbors, who had their roofs ___3___ by companies, Dawson worked with his own hands. ''I''d rather you ___4___ my tools alone,'' he''d tell the young helpers with a smile.","blank_no":2,"options":["than","then","that","as"],"answer_index":0,"explanation_cn":"would sooner A than B,表“宁愿 A 不愿 B”:rebuild it than hire a crew。✓ he would sooner rebuild it than hire a crew."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',7,NULL,'cloze','{"stem":"第 3 空","context":"Old Mr. Dawson would rather ___1___ everything himself. When a storm destroyed his fence, he would sooner rebuild it ___2___ hire a crew. Unlike his neighbors, who had their roofs ___3___ by companies, Dawson worked with his own hands. ''I''d rather you ___4___ my tools alone,'' he''d tell the young helpers with a smile.","blank_no":3,"options":["repaired","repair","repairing","to repair"],"answer_index":0,"explanation_cn":"have sth done,用过去分词:had their roofs repaired。✓ neighbors who had their roofs repaired by companies."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',7,NULL,'cloze','{"stem":"第 4 空","context":"Old Mr. Dawson would rather ___1___ everything himself. When a storm destroyed his fence, he would sooner rebuild it ___2___ hire a crew. Unlike his neighbors, who had their roofs ___3___ by companies, Dawson worked with his own hands. ''I''d rather you ___4___ my tools alone,'' he''d tell the young helpers with a smile.","blank_no":4,"options":["left","leave","to leave","leaving"],"answer_index":0,"explanation_cn":"would rather + 某人 + 过去式:would rather you left。✓ I''d rather you left my tools alone."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',8,NULL,'choice','{"stem":"Why did Dawson refuse his neighbors'' offer to hire a crew?","options":["He disliked his neighbors","He was out of town","He would rather fix the fence himself","He had no money"],"answer_index":2,"explanation_cn":"课文说 a handyman who would rather fix a thing himself than have it done by anyone else——他宁愿自己修,所以谢绝了雇工人的好意。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',8,NULL,'choice','{"stem":"What did most townspeople do that Dawson never did?","options":["They sold their old tools","They had their roofs and cars fixed by companies","They built their own houses","They moved away to the city"],"answer_index":1,"explanation_cn":"课文说 Most people would have their roofs repaired, their cars fixed…by companies——镇上大多数人请公司代劳,唯独 Dawson 不肯。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',8,NULL,'choice','{"stem":"How did the town honor Dawson in the end?","options":["They dedicated a plaque to his memory","They built him a new house","They named a river after him","They gave him a large sum of money"],"answer_index":0,"explanation_cn":"课文说 they dedicated a small brass plaque…to the memory of the most valiant handyman——全镇立铜牌纪念他。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',9,NULL,'choice','{"stem":"你想说\"我宁愿自己动手,也不愿雇人\"(would rather ... than):","options":["I''d rather doing it myself than hire someone.","I''d rather did it myself than hire someone.","I''d rather do it myself than hire someone.","I''d rather do it myself than to hire someone."],"answer_index":2,"explanation_cn":"“宁愿 A 不愿 B”用 would rather + 原形 A than + 原形 B。✓ I''d rather do it myself than hire someone. 场合:说明自己在两件事之间的偏好。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',9,NULL,'choice','{"stem":"你想说\"我希望你别动我的工具\"(would rather + 某人 + 过去式):","options":["I''d rather you won''t touch my tools.","I''d rather you didn''t touch my tools.","I''d rather you don''t touch my tools.","I''d rather you not touch my tools."],"answer_index":1,"explanation_cn":"“希望别人别做某事”用 would rather + 某人 + didn''t + 原形。✓ I''d rather you didn''t touch my tools. 场合:委婉地请别人别做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',9,NULL,'choice','{"stem":"你想说\"他们请公司来修屋顶\"(have sth done):","options":["They had repaired their roof by a company.","They had their roof repairing by a company.","They had their roof repair by a company.","They had their roof repaired by a company."],"answer_index":3,"explanation_cn":"“请人把某事做好”用 have + 某物 + 过去分词:had their roof repaired。✓ They had their roof repaired by a company. 场合:表示某事是请别人做的,不是自己做的。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"remarkable 的意思是:","options":["害怕的","便宜的","非凡的,了不起的","普通的"],"answer_index":2,"explanation_cn":"remarkable = 非凡的、了不起的。✓ a remarkable handyman."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"valiant 的意思是:","options":["懒惰的","英勇的,顽强的","富有的","胆小的"],"answer_index":1,"explanation_cn":"valiant = 英勇的、顽强的。✓ the most valiant handyman."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"\"He would rather ___ it himself than pay a crew.\"(would rather 后接动词原形)","options":["do","doing","to do","did"],"answer_index":0,"stem_cn":"他宁愿自己做,也不愿花钱雇人。","explanation_cn":"would rather 后接动词原形:would rather do。✓ He would rather do it himself. ✗ to do / doing / did:要用原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"\"I''d rather you ___ my tools alone.\"(would rather + 某人 + 过去式)","options":["leaving","left","to leave","leave"],"answer_index":1,"stem_cn":"我希望你别动我的工具。","explanation_cn":"would rather + 某人 + 过去式:would rather you left。✓ I''d rather you left my tools alone. ✗ leave / to leave / leaving:这个句式要用过去式 left。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"\"would rather ... than ...\" 的意思是:","options":["要么……要么……","既……又……","宁愿……也不愿……","越……越……"],"answer_index":2,"explanation_cn":"would rather ... than ... = 宁愿……也不愿……。✓ would rather fix it than pay someone 宁愿自己修也不愿花钱雇人。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"\"have sth done\" 的意思是:","options":["亲自做某事","(请人)把某事做好","忘记做某事","拒绝做某事"],"answer_index":1,"explanation_cn":"have sth done = (请/让别人)把某事做好。✓ have the roof repaired 请人把屋顶修好。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"Why did Dawson rebuild the fence himself?","options":["The crew never came","The storm was still going on","He would rather not have it done by others","He could not afford a crew"],"answer_index":2,"passage":"Everyone in our little town knew Old Mr. Dawson, a remarkable handyman who would rather fix a thing himself than have it done by anyone else. When a winter storm destroyed part of his fence, his neighbors offered to hire a crew from the city, but Dawson only smiled. ''I''d sooner do it with my own two hands,'' he said, and he had the whole fence standing again within a week. Most people in town would have their roofs repaired, their cars fixed, and their yards dug by companies. Not Dawson. He would rather spend a whole afternoon under a leaking faucet than call a plumber, and he would sooner walk five miles than have someone drive him. Each morning he liked to have a good look at his tools, and he''d rather work late by flashlight than leave a job half done. If a young man offered to help, Dawson would say kindly, ''I''d rather you watched and learned.'' And if anyone picked up his favorite wrench without asking, he''d say, ''I''d rather you didn''t.'' He fixed everything promptly and never charged a cent. When at last he grew too old to climb ladders, the whole town came together, and after his funeral they dedicated a small brass plaque by the town hall to the memory of the most valiant handyman anyone could remember. A band played, and everyone agreed that they would rather have known one Mr. Dawson than a hundred famous men.","explanation_cn":"课文说 a handyman who would rather fix a thing himself than have it done by anyone else——他宁愿自己动手,不愿别人代劳,所以亲手重修篱笆。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"What did the town do after his funeral?","options":["They sold all his tools","They forgot about him","They closed the town hall","They dedicated a plaque to his memory"],"answer_index":3,"passage":"Everyone in our little town knew Old Mr. Dawson, a remarkable handyman who would rather fix a thing himself than have it done by anyone else. When a winter storm destroyed part of his fence, his neighbors offered to hire a crew from the city, but Dawson only smiled. ''I''d sooner do it with my own two hands,'' he said, and he had the whole fence standing again within a week. Most people in town would have their roofs repaired, their cars fixed, and their yards dug by companies. Not Dawson. He would rather spend a whole afternoon under a leaking faucet than call a plumber, and he would sooner walk five miles than have someone drive him. Each morning he liked to have a good look at his tools, and he''d rather work late by flashlight than leave a job half done. If a young man offered to help, Dawson would say kindly, ''I''d rather you watched and learned.'' And if anyone picked up his favorite wrench without asking, he''d say, ''I''d rather you didn''t.'' He fixed everything promptly and never charged a cent. When at last he grew too old to climb ladders, the whole town came together, and after his funeral they dedicated a small brass plaque by the town hall to the memory of the most valiant handyman anyone could remember. A band played, and everyone agreed that they would rather have known one Mr. Dawson than a hundred famous men.","explanation_cn":"课文说 they dedicated a small brass plaque…to the memory——他去世后全镇立铜牌纪念他。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"What did Dawson say when a young man offered to help?","options":["''I''d rather you watched and learned''","''I''ll pay you well''","''Go home now''","''Please do it for me''"],"answer_index":0,"audio":"Everyone in our little town knew Old Mr. Dawson, a remarkable handyman who would rather fix a thing himself than have it done by anyone else. When a winter storm destroyed part of his fence, his neighbors offered to hire a crew from the city, but Dawson only smiled. ''I''d sooner do it with my own two hands,'' he said, and he had the whole fence standing again within a week. Most people in town would have their roofs repaired, their cars fixed, and their yards dug by companies. Not Dawson. He would rather spend a whole afternoon under a leaking faucet than call a plumber, and he would sooner walk five miles than have someone drive him. Each morning he liked to have a good look at his tools, and he''d rather work late by flashlight than leave a job half done. If a young man offered to help, Dawson would say kindly, ''I''d rather you watched and learned.'' And if anyone picked up his favorite wrench without asking, he''d say, ''I''d rather you didn''t.'' He fixed everything promptly and never charged a cent. When at last he grew too old to climb ladders, the whole town came together, and after his funeral they dedicated a small brass plaque by the town hall to the memory of the most valiant handyman anyone could remember. A band played, and everyone agreed that they would rather have known one Mr. Dawson than a hundred famous men.","explanation_cn":"课文说 Dawson would say kindly, ''I''d rather you watched and learned.''——有人想帮忙时他这样回答。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l14',10,NULL,'choice','{"stem":"How did Dawson prefer to travel short distances?","options":["He asked a neighbor to drive","He would sooner walk than have someone drive him","He rode a horse","He always took the bus"],"answer_index":1,"audio":"Everyone in our little town knew Old Mr. Dawson, a remarkable handyman who would rather fix a thing himself than have it done by anyone else. When a winter storm destroyed part of his fence, his neighbors offered to hire a crew from the city, but Dawson only smiled. ''I''d sooner do it with my own two hands,'' he said, and he had the whole fence standing again within a week. Most people in town would have their roofs repaired, their cars fixed, and their yards dug by companies. Not Dawson. He would rather spend a whole afternoon under a leaking faucet than call a plumber, and he would sooner walk five miles than have someone drive him. Each morning he liked to have a good look at his tools, and he''d rather work late by flashlight than leave a job half done. If a young man offered to help, Dawson would say kindly, ''I''d rather you watched and learned.'' And if anyone picked up his favorite wrench without asking, he''d say, ''I''d rather you didn''t.'' He fixed everything promptly and never charged a cent. When at last he grew too old to climb ladders, the whole town came together, and after his funeral they dedicated a small brass plaque by the town hall to the memory of the most valiant handyman anyone could remember. A band played, and everyone agreed that they would rather have known one Mr. Dawson than a hundred famous men.","explanation_cn":"课文说 he would sooner walk five miles than have someone drive him——短途他宁愿自己走,也不愿让人开车送。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
